window.HP_EXPL = {"vt2025":{"v0":{"1":{"t":"Basal betyder grundläggande eller fundamental - något som utgör basen. Därför är D grundläggande synonymen.","f":0},"2":{"t":"En defekt är ett fel eller en brist, något som saknas eller är trasigt. B brist matchar bäst.","f":0},"3":{"t":"Att länsa betyder att tömma på vätska (t.ex. länsa en båt på vatten). Därför D tömma.","f":0},"4":{"t":"Gensvar betyder svar eller reaktion på något - en respons. Därför E respons.","f":0},"5":{"t":"Kontroversiell betyder omdiskuterad, något folk är oense om. C omtvistad är synonymen.","f":0},"6":{"t":"Eskapader är vågade eller vilda tilltag och upptåg - äventyr. Därför D äventyr.","f":0},"7":{"t":"Att förfoga över något betyder att ha det till sitt förfogande, att ha tillgång till det. Därför A ha.","f":0},"8":{"t":"Diger betyder tjock, omfångsrik och stor (t.ex. en diger bok). Därför B stor.","f":0},"9":{"t":"Aversion betyder stark motvilja eller avsky mot något. E motvilja är synonymen.","f":0},"10":{"t":"Fåfängt betyder förgäves, utan resultat - något gjort utan att det lönar sig. Därför C resultatlöst.","f":0},"11":{"t":"Textens kärna är att man utfört den etablerade talamotomin på ett nytt, icke-invasivt sätt med högintensivt ultraljud. C fångar denna huvudpoäng bäst.","f":0},"12":{"t":"Författaren påpekar själv att man inte gjort en blindad studie med kontrollgrupp, vilket gör placebokomponenten svårbedömd och effekterna osäkra. Alltså D - osäkra pga studiens utformning.","f":0},"13":{"t":"Texten hånar att bankerna själva räknar med interna modeller som matas med naiva antaganden och därför ger missvisande riskbedömningar. Det är den framställda svagheten. B.","f":0},"14":{"t":"Författaren betonar att bolånemarginalerna ökat dramatiskt och att avkastningen på kapitalet är orimligt hög (dubblats, upp mot 25%). D - bankerna tjänar orimligt mycket.","f":0},"15":{"t":"Genom exemplen på personer som rör sig mellan stat och storbanker antyder författaren att relationen är osund och delvis korrupt. Därför B.","f":0},"16":{"t":"Tonen är genomgående ironisk och spydig med sarkastiska liknelser (korvmaskiner, snömos). A syrliga sarkasmen fångar detta.","f":0},"17":{"t":"Psykologen föreslår att hon kan placera det änglalika utanför sig själv; en djävul skulle på motsvarande sätt låta henne placera/distansera det onda utanför sig. Därför B.","f":0},"18":{"t":"Den upprepande formuleringen visar att ängeln är så laddad med tolkningar och symbolik att den knappt kan vara bara en ängel. D - tungt lastad med symbolisk betydelse.","f":0},"19":{"t":"Texten säger att gudarna vid övergången till en Gud sände oss änglarna - de fyllde samma funktion för människorna, därför liknar ängeln Venus. C.","f":0},"20":{"t":"Författaren längtar efter de ordlösa upplevelserna bortom beskrivning, ögonblick när sinnet är vidöppet och saknar ord. Därför A ordlösa erfarenheter.","f":0},"21":{"t":"Läkemedlet ska öka mängden dopamin: antingen förbättra verkan eller bromsa nedbrytningen av signalsubstansen. Bara B förstärker (inte hämmar) effekten och passar 'eller'.","f":0},"22":{"t":"Turister väljer den spektakulära vägen genom en ravin som kantas av (omges av) åttio meter höga klippor. B spektakulära - kantas passar bäddens innehåll.","f":0},"23":{"t":"Spisen hade ett betydande ekonomiskt värde; inköpet förde med sig merkostnader eftersom gamla grytor måste ersättas av nya kärl. C.","f":0},"24":{"t":"Häggen förekommer endast enstaka/spritt som buske högst upp - sporadiskt. D fångar den oregelbundna förekomsten.","f":0},"25":{"t":"Att allmänheten vill ha högre straff är en sanning med modifikation, eftersom åsikterna är så spridda att man inte hittar någon enhetlig linje. A.","f":0},"26":{"t":"Både 'kvinna och man' och 'varken kvinna eller man' är former av androgyni (könsblandning). Därför A.","f":0},"27":{"t":"Parlamentet väntas anta förslaget; det vore i så fall en fjäder i hatten (en ära) för Cykelfrämjandet. C.","f":0},"28":{"t":"Lokala prognoser kan inte direkt härledas ur ett större sammanhang, men det finns ömsesidig påverkan mellan det lokala och det globala. B.","f":0},"29":{"t":"Information på nätet fragmentiseras (splittras), vilket ökar värdet av att gå upp i romanen med dess obrutna handling. A.","f":0},"30":{"t":"Yrken som förr sågs som strikt förbehållna människan kan nu digitaliseras. Förbehållna = reserverade för. D.","f":0}},"v1":{"1":{"t":"Olidlig betyder outhärdlig, något man inte står ut med. Det matchar 'omöjlig att uthärda'.","f":0},"2":{"t":"Återstoden = det som är kvar, alltså resten.","f":0},"3":{"t":"Klandervärt betyder klandervärdigt, något som förtjänar kritik. Synonymt med förkastligt.","f":0},"4":{"t":"Intervention betyder att gripa in i ett förlopp, alltså ett ingripande.","f":0},"5":{"t":"Bistå betyder att stödja eller hjälpa någon.","f":0},"6":{"t":"Parafras är en omskrivning, att säga samma sak med andra ord.","f":0},"7":{"t":"Gedigen betyder gedigen/rejäl och massiv, alltså solid.","f":0},"8":{"t":"Hålla till godo med betyder att acceptera och nöja sig med det man får.","f":0},"9":{"t":"Vånda betyder plåga, kval eller ångest.","f":0},"10":{"t":"Fingerad betyder uppdiktad eller påhittad, inte äkta.","f":0},"11":{"t":"Gun Widmark växte upp med dialekt men valde att tala ren rikssvenska, även privat. Exemplet visar hur starkt normer kring språket kan styra hur människor väljer att prata.","f":0},"12":{"t":"Förr sågs dialekter som mossiga och kopplade till bondesamhället; idag är de omhuldade och till och med moderna i reklam. Det som förändrats är dialekternas status bland folk i allmänhet.","f":0},"13":{"t":"Texten reder ut varför just belgisk blå kom att symbolisera monstret och genmanipulation, alltså mekanismerna bakom den infekterade debatten.","f":0},"14":{"t":"Ja-sidan hade lovat att Sverige skulle hållas fritt från belgisk blå, men insemineringen skedde ändå. Nederlaget bestod i att kampanjen lovat mer än den kunde hålla.","f":0},"15":{"t":"Frågan besvaras: andra extremt avlade raser som Cobb och British united turkey väcker inte samma reaktion eftersom vi människor har svårt att relatera till fåglar.","f":0},"16":{"t":"Texten betonar att belgisk blås extrema muskler inte beror på hormoner eller genmanipulation utan på traditionell, om än extrem, avel. Rasen visar att även avel kan ge dramatiska genförändringar.","f":0},"17":{"t":"Texten kretsar mest kring den ökade formaliseringen/proven (första trenden) och att ämnet nu betonar förmågor och kompetenser (fjärde trenden). Alltså första och fjärde.","f":0},"18":{"t":"När content/skills-debatten återkommer riktar sig författarna särskilt in på om de två kunskapsformerna verkligen går att skilja åt inom historieämnet.","f":0},"19":{"t":"Författarna menar att skriftliga prov är ett av flera redskap och att de behöver förnyas innehållsmässigt för att passa ämnets nya krav.","f":1},"20":{"t":"Texten är främst beskrivande och diskuterar förutsättningarna för bedömning i historieämnet, snarare än att argumentera för en viss lösning.","f":0},"21":{"t":"Saliven ger bara en indikation om de senaste minuterna, i kontrast till håret som visar månader. En fingervisning betyder just en antydan/hint.","f":0},"22":{"t":"Kontrasten är egoister mot altruister (osjälviska). Samarbetet beskrivs som beroende av tillit, alltså villkorat.","f":0},"23":{"t":"Man anmäler ett förtal till polisen, ansöker om stämning hos domstol, och en process mellan enskilda är civilrättslig.","f":0},"24":{"t":"En mörk humor beskrivs bäst som morbid, alltså med dragning åt det dystra och makabra.","f":0},"25":{"t":"Oron är inte ras utan att spårstabiliteten inte kan bibehållas vid höga hastigheter, och att underhållskostnaden skulle skjuta i höjden.","f":0},"26":{"t":"Arbetet var tillfälligt och på deltid, så väverskorna rekryterades på informell (icke-formaliserad) basis från närområdet.","f":0},"27":{"t":"Göteborg anlades som en viktig knutpunkt i militärstaten och byggdes som en starkt befäst (fortifierad) stad.","f":0},"28":{"t":"Att fåglar blir berusade är omdiskuterat; sidensvansen har en exceptionellt stor lever som bryter ner alkohol, och hög alkoholhalt kan ha påverkat deras koordination.","f":0},"29":{"t":"Det utmärkande är att repertoaren (musikurvalet) huvudsakligen består av västerländsk konstmusik.","f":0},"30":{"t":"Läroplanen måste stipulera (fastställa) vad ämnen ska innehålla, och man måste i grunden bejaka (acceptera) tanken att kunskap kan mätas.","f":0}},"q0":{"1":{"t":"4x+16=6x-8. Flytta: 16+8=6x-4x, alltså 24=2x, x=12.","f":0},"2":{"t":"Gör om till cm: 2 m=200 cm, 2 dm=20 cm, 2 mm=0,2 cm. Volym=200·20·0,2=800 cm³.","f":0},"3":{"t":"27=3³, så 3^(2x)=3³ ger 2x=3, alltså x=3/2.","f":0},"4":{"t":"x=y+7 och x+y=33 ger 2y+7=33, y=13, x=20. Produkten xy=20·13=260.","f":0},"5":{"t":"(6/25)/(36/5)=6/25·5/36=30/900=1/30.","f":0},"6":{"t":"x(x+1) är produkten av två på varandra följande heltal, alltid jämnt. Endast 42=6·7 passar (och är jämnt). 37 och 81 är udda, 54 är inte n(n+1).","f":0},"7":{"t":"Testa f(a): för B, f(x)=2x−a ger f(a)=2a−a=a. Gäller alltid. (A ger 1+a, C ger a², D ger −a²+a³.)","f":0},"8":{"t":"2,1/3=0,7 och 10⁶/10⁴=10². 0,7·100=70.","f":0},"9":{"t":"Löser ut: y=−2x+2. Lutning −2 (nedåtlutande) och skär y-axeln i 2, x-axeln i 1. Det stämmer med graf C.","f":0},"10":{"t":"Samma nämnare: (a+b)/b+(b−a)/b=(a+b+b−a)/b=2b/b=2.","f":0},"11":{"t":"Median av 3,5,6,6,8 är 6. Lägger man till ett siffervärde 1–9 blir det 6 tal; medianen är snittet av 3:e och 4:e talet, som som mest blir 6 (aldrig >6). Sannolikheten att medianen ökar är 0.","f":0},"12":{"t":"Tre hela cirklar=3·π·1²=3π. Sektorerna som ligger inne i triangeln har vinkelsumma 180°=halva varv, alltså 0,5π. Skuggat=3π−0,5π=2,5π cm².","f":0},"13":{"t":"I: 4% av 40=1,6. II: 5% av 35=1,75. II är större.","f":0},"14":{"t":"x>y och z>y säger båda bara att de är större än y; förhållandet mellan x och z är okänt. Otillräcklig information.","f":0},"15":{"t":"Lutning=Δy/Δx. I: (−3−0)/(−1−0)=3. II: (3−0)/(1−0)=3. Lika.","f":0},"16":{"t":"x=−1/3 i x−y=1/3 ger −1/3−y=1/3, y=−2/3. II: 2x=−2/3. Lika.","f":0},"17":{"t":"Rätvinklig triangel: AB=2, hypotenusa BC=√5, så AC=√(5−4)=1. Area=½·2·1=1. Kvadraten har sida 1, area 1. Lika.","f":0},"18":{"t":"y/x² mot y²/x beror helt på y (tecken/storlek), som är okänt. Otillräcklig information.","f":0},"19":{"t":"Medelvärdet=(5/7+5/2+5/6)/3=5·(1/7+1/2+1/6)/3≈5·0,81/3≈1,35, alltså >1. I är större.","f":0},"20":{"t":"Tid=sträcka/fart. Adam: 45/27≈1,67 h. David: 40/25=1,6 h. Adams tid är längre. I större.","f":0},"21":{"t":"I triangel CDE: x=180−85−40=55°. Eftersom DE∥AB är vinkel A=vinkel CDE=85°, så y=vinkel B=180−55−85=40°. x=55>y=40. I större.","f":0},"22":{"t":"Kvot 1 och rest 1 betyder x=1·y+1=y+1, alltså x>y. I större.","f":0},"23":{"t":"(1): herr i mitten, barn till vänster om dam ⇒ barn=vänster, dam=höger. Räcker. (2): barn längst vänster, herr vänster om dam ⇒ herr mitten, dam=höger. Räcker. Var för sig.","f":0},"24":{"t":"(1) ger bara att Mia har kortare restid, (2) bara att Nellie har längre väg. Tillsammans: Mia har både kortare tid och kortare väg ⇒ fart=sträcka/tid kan inte avgöras. Ingetdera räcker.","f":0},"25":{"t":"Tillsammans: jacka först, skor före både vantar och mössa ⇒ skor näst först, mössa ej sist ⇒ mössa 3:a, vantar sist. Ordning: jacka, skor, mössa, vantar. Krävs båda.","f":0},"26":{"t":"x=5y. (1): 5y+y=24 ⇒ y=4, x=20, x−y=16. (2): 5y²=80 ⇒ y=4, x=20, x−y=16. Var för sig.","f":0},"27":{"t":"(2) ger direkt: b+p=65 och b−p=39 ⇒ 2p=26, p=13 pärmar. (1) ger bara Camillas böcker (52), inte pärmarna. Endast (2).","f":0},"28":{"t":"Clowner=0,6a. (1): 2·0,6a−0,5a=0,7a=7 ⇒ a=10. (2): a−0,6a=0,4a=4 ⇒ a=10. Var för sig.","f":0},"29":{"t":"Minst förändring i kronor: Sporthallar m.m. 3702→3688 (−14). Övriga ändras mer (Skidsport −448, Sportklubbar −334, Tävlingsstall −79).","f":0},"30":{"t":"Spel- och vadhållning 24 790 av totalt 77 461 ≈ 0,32 ≈ 1/3.","f":0},"31":{"t":"Artistisk: 4817→3439, minskning 1378. Litterärt: 4941→4792, minskning 149. Skillnad=1378−149=1229 miljoner kr.","f":0},"32":{"t":"Metod: läs av de två högsta enskilda platssegmenten i 1997-stapeln och addera dem. Svenska Högarna är den klart största platsen (det stora grå blocket, ~2000-2100). Näst störst bland platserna 1997 är ungefär lika stort. De två största segmenten summerar till ca 4500. Svar B. Förklaringen bör namnge/peka ut de två segmenten och deras avlästa värden, inte bara säga 'ca 4500'.","f":0},"33":{"t":"År 2000 är stapeln mellan de utsatta åren 1999 och 2001. Jämför för var och en av svarsalternativens platser (Nåttaröfladen, Bullerö, Svenska Högarna, Söderarm) hur stort segmentet är 2000 jämfört med 1999. Trots att totalen minskade 2000 mot 1999 är Bullerös segment större år 2000 - alltså räknades fler ejdrar på Bullerö. Svar B. Förklaringen bör visa den konkreta jämförelsen segment för segment i stället för att medge att den inte kan bekräftas.","f":0},"34":{"t":"Minskningen = total stapelhöjd första året minus sista året: total(1997) ~13000 minus total(2015) ~1900, dvs en minskning på ca 11000 ejdrar. Leta sedan reda på det år vars totala stapelhöjd är ungefär lika stor som denna minskning (~11000). Enligt diagrammet stämmer det med 2003. Svar B. Nuvarande förklaring har inbördes osäkra siffror (11000 vs total 2003) och medger att den inte kan bekräftas - den bör ange de avlästa totalhöjderna tydligare.","f":0},"35":{"t":"20 år eller yngre = grupperna −18 (12 858) och 19–20 (11 340) = 24 198. Totalt ≈ 40 588. Andel ≈ 0,60 = 60 %.","f":0},"36":{"t":"Högst poäng: 66+ (råpoäng ~121, normerad 1,32). Lägst: 21–22 (råpoäng ~89, normerad 0,83). Skillnad: råpoäng ~32 och normerad 1,32−0,83=0,49.","f":0},"37":{"t":"Antalet provdeltagare sjunker konsekvent med stigande ålder (12 858 → 11 340 → … → 18). Övriga påståenden stämmer inte (poängen är inte monotont ökande, åldersfördelningen är ojämn).","f":0},"38":{"t":"Summan av alla kategorier 1990: familje-/partnervåld ~28 + spontanbråk ~43 + rån ~5 + kriminella/sexuellt ~fåtal ≈ 85 fall.","f":0},"39":{"t":"Avläs cirkeldiagrammet: Mord upptar drygt halva cirkeln (~55%), Dråp den näst största delen (~30%) och Vållande till annans död minst (~15%), med Dråp tydligt större än Vållande. Leta i procentdiagrammet efter det år där Mord ligger runt 55% och Dråp är klart större än Vållande - det stämmer med 1995. Svar B. Förklaringen bör motivera varför just 1995 och inte det närliggande alternativet 1996, i stället för att bara säga att den inte kan bekräftas helt.","f":0},"40":{"t":"År 2000: spontanbråk och dispyter ~20 fall av totalt ~64 (summan av alla kategorier) ≈ 0,30 = 30 %.","f":0}},"q1":{"1":{"t":"(x+4)(2x+8) = (x+4)·2(x+4) = 2(x+4)². Bryt ut 2 ur andra faktorn så syns kvadraten.","f":0},"2":{"t":"a är jämnt, b udda. ab = jämnt·udda = jämnt. (a−b och a+b blir udda; ab+b² = jämnt+udda = udda.) Bara ab är säkert jämnt.","f":0},"3":{"t":"Medelvärde = (2x+3x+5x+8x)/4 = 18x/4 = 4,5x = 45 → x = 10.","f":0},"4":{"t":"5/4 = 1,25. 4 % av 1,25 = 0,04·1,25 = 0,05.","f":0},"5":{"t":"−4x+7 = −9 → −4x = −16 → x = 4.","f":0},"6":{"t":"Rektangeln FABC: 10·7 = 70. Trapetsen EDCF upptill: parallella sidor 6 och 10, höjd 5 → (6+10)/2·5 = 40. Totalt 70+40 = 110 cm².","f":0},"7":{"t":"30 % rabatt ger 0,7p, sedan 50 % rabatt ger 0,5·0,7p = 0,35p = 70 → p = 200 kr.","f":0},"8":{"t":"Sätt in 2x+3 i f: f(2x+3) = 2(2x+3)+3 = 4x+6+3 = 4x+9.","f":0},"9":{"t":"Kolla Pythagoras. A: 5²+12² = 25+144 = 169 = 13². Stämmer, alltså rätvinklig. Övriga alternativ uppfyller inte a²+b²=c².","f":0},"10":{"t":"Sträcka: 0,5h·30 = 15 km och 1h·60 = 60 km, totalt 75 km. Tid 1,5 h. Medelfart = 75/1,5 = 50 km/h (inte medel av 30 och 60).","f":0},"11":{"t":"x+y = 100 och y = x+200. Sätt in: x+(x+200) = 100 → 2x = −100 → x = −50.","f":0},"12":{"t":"√9 = 3, √36 = 6, produkt = 18. √18 = √(9·2) = 3√2.","f":0},"13":{"t":"(x+y)² = x²+2xy+y² och (x−y)² = x²−2xy+y². Med x,y>0 är 2xy>0, så II är större.","f":0},"14":{"t":"I = (4·6·8)/(8x) = 192/(8x) = 24/x. II = (2·3·4)/x = 24/x. De är lika.","f":0},"15":{"t":"I: √(6²+8²) = √100 = 10. II: √(7²+7²) = √98 ≈ 9,9. I är större.","f":0},"16":{"t":"I = √(10⁸) = 10⁴ = 10000. II = 10^√8 ≈ 10^2,83 ≈ 676. I är mycket större.","f":0},"17":{"t":"Entalssiffran E = 2·tiotal = 4·hundratal. H=1 ger 124 (E=4), H=2 ger 248 (E=8). E kan vara 4 eller 8, så jämförelsen med 6 kan inte avgöras.","f":0},"18":{"t":"(x−3)(x+2)=0 ger x=3 eller x=−2. Positiva lösningen är 3, som är större än 2.","f":0},"19":{"t":"I trianglarna gäller tan v = höjd/DQ och tan w = höjd/BP (samma höjd = rektangelns sida). DQ>BP ger tan v < tan w, alltså v < w. II större.","f":0},"20":{"t":"Högerledet 2(x+½) = 2x+1 = vänsterledet. Likheten gäller för alla x, så x är obestämt och kan inte jämföras med −½.","f":0},"21":{"t":"1◇2 = 1/2. Sedan (1/2)◇3 = (1/2)/3 = 1/6. II = 1/3 > 1/6, så II större.","f":0},"22":{"t":"P(minst en klave) = 1 − P(ingen) = 1 − (1/2)³ = 7/8 = 0,875, vilket är större än 2/3 ≈ 0,67.","f":0},"23":{"t":"(1) ger vindruvor = 2·melon, men antalet okänt. (2) ger summan 57. Tillsammans: 2M+M = 57 → M = 19, så 19 fler vindruvor. Båda behövs.","f":0},"24":{"t":"(1): Alexandra i köket, Björn ej hall → Björn vardagsrum, Charlotte hall. (2): Björn vardagsrum, Charlotte ej kök → Charlotte hall. Vardera påståendet räcker ensamt.","f":0},"25":{"t":"(1): 0,5x − 0,3x = 0,2x = 22 → x = 110, entydigt. (2): delbart med 110 ger 110, 220, … flera värden. Endast (1) räcker.","f":0},"26":{"t":"(1): både senap+ketchup = 1/9·27 = 3 = 60 % av senap → senap = 5, men ketchup okänt. (2): senap = 5, varken = 15. Tillsammans: union = 27−15 = 12 = 5 + ketchup − 3 → ketchup = 10.","f":0},"27":{"t":"(1): x=z=60° ger alla vinklar 60° (liksidig), då är AB=BC, alltså AB>BC falskt — avgjort. (2): x=180−y betyder x = vinkel B, vilket ger BC=AC men inget om AB. Endast (1) räcker.","f":0},"28":{"t":"(1): medianen 0 kan behållas av flera olika par. (2): medelvärdet ändras för många par. Även tillsammans pekar de inte ut ett unikt par som togs bort.","f":0},"29":{"t":"Yrket 'övriga maskinoperatörer och montörer' har totalt 29 612, män 22 183. Kvinnor = 29 612 − 22 183 = 7 429.","f":0},"30":{"t":"Andel män = män/totalt. Kockar: män = 35 326 − 18 764 = 16 562, andel ≈ 47 %. Det är störst av de fyra alternativen (Vårdbiträden ~18 %, Försäljare fackhandel ~38 %, Övrig kontorspersonal ~24 %).","f":0},"31":{"t":"Datatekniker totalt 41 637, män 33 002 → kvinnor = 8 635. Andel = 8 635/41 637 ≈ 0,21 ≈ 1/5.","f":0},"32":{"t":"Åldersgrupp 5–9 i diagrammet: ~7,5 (Sverige) och ~12 (utomlands) per 100 000. Med 610 000 inv.: 7,5·6,1 ≈ 45 resp 12·6,1 ≈ 75.","f":0},"33":{"t":"Förhållandet 35:65 betyder andel smittade i Sverige ≈ 35 %. För 25–29 år: svart/(svart+grå) ≈ 8/(8+14) ≈ 36 %, närmast 35 %.","f":0},"34":{"t":"Diagrammet ger incidens (per 100 000). För att räkna om till faktiskt antal personer behövs antalet invånare i var och en av åldersgrupperna, sedan summeras. Alternativ C.","f":0},"35":{"t":"På kartan ligger Norrby uppe till vänster (nordväst) och Edeby nere till höger (sydost), alltså sydostlig riktning från Norrby till Edeby.","f":0},"36":{"t":"Följer man den kortaste stigen (streckad linje) från fornborgen (RAÄ 20 i söder) till kyrksymbolen och mäter mot skalstocken blir det ca 2,5 km.","f":0},"37":{"t":"Området innanför Edebys gårdsägogräns (streckprickad linje) motsvarar mot skalan ungefär 2,4 km².","f":0},"38":{"t":"Referenslinjen ligger högt (~340 DU) och de flesta uppmätta årsvärdena ligger under den. Ungefär dubbelt så många år är under som över → förhållandet ≈ 1:2.","f":0},"39":{"t":"Läs av de sex årsvärdena 1995–2000 mot rutnätet (var 10:e DU). Grafen är roterad och svåravläst, så använd referenslinjen (~340 DU) och rutnätslinjerna som stöd. Mitten av 1990-talet är en svacka (1995–1996 kring 318–322 DU), 1997–1998 stiger mot ~335–340 DU och 1999–2000 ligger kring 325–330 DU. Summan av de sex åren delat på 6 ger ett medelvärde på ca 327 DU, dvs alternativ B. (Värdet ligger nära gränsen mot 330, så noggrann avläsning mot rutnätet krävs.)","f":0},"40":{"t":"1993 var ett ovanligt lågt ozonår med kraftig återhämtning till 1994, vilket ger den största procentuella förändringen mellan två på varandra följande år.","f":0}}},"ht2024":{"v0":{"1":{"t":"Att hysa agg betyder att bära på fientlighet eller groll mot någon. Det motsvarar att vara fientligt inställd.","f":0},"2":{"t":"Ett kontinuum är en sammanhängande, obruten följd utan avbrott. Därför obruten följd.","f":0},"3":{"t":"Vimmelkantig betyder yr och förvirrad i huvudet. Synonymen är yr.","f":0},"4":{"t":"Krill är små räkliknande havsdjur, alltså kräftdjur. Därför kräftdjur.","f":0},"5":{"t":"Restriktiv betyder återhållsam och sparsam, att man begränsar sig. Motsvarar återhållsam.","f":0},"6":{"t":"Ett särdrag är ett kännetecken som utmärker och särskiljer något, alltså en utmärkande egenskap.","f":0},"7":{"t":"Osökt betyder otvunget och naturligt, utan ansträngning. Synonymen är naturligt.","f":0},"8":{"t":"Empati är förmågan att sätta sig in i andras känslor, alltså inlevelseförmåga.","f":0},"9":{"t":"Att bordlägga ett ärende betyder att skjuta upp beslutet till senare. Motsvarar uppskjuta.","f":0},"10":{"t":"Taktfull betyder hänsynsfull och känslig för andras situation, alltså finkänslig.","f":0},"11":{"t":"Texten säger att en andra kull normalt inte förekommer och att kanadagäss inte får mer än en kull per år. Alltså gäller generellt en kull per säsong.","f":0},"12":{"t":"Avslutningen föreslår att man studerar andrakullar i tempererade områden med märkning och dna-analys för att säkra att det rör sig om äkta andrahäckningar, dvs. finna fler belägg som fallet på Nidingen.","f":0},"13":{"t":"Modellen sägs träna fokus och reflektion som påverkar alla ämnen och ger goda resultat, alltså förmågor till nytta i alla skolämnen.","f":0},"14":{"t":"Sista meningen lyfter fram att Tuvas egen tanke finns nedtecknad på papperet framför henne, vilket betonar värdet av det individuella tankearbetet.","f":0},"15":{"t":"Moula menar att skolan prioriterar det ämnesorienterade och teknik-/matematikkunskap, vilket antyder en begränsad syn på vad som är viktig kunskap.","f":0},"16":{"t":"Texten betonar att skolan ska ge redskap för livet och förmåga att hantera svåra situationer. Rubriken Redo för livets utmaningar fångar helheten bäst.","f":0},"17":{"t":"Verksamheten beskrivs ha stora samhällsekonomiska effekter, och förslagen syftar till att bibehålla och öka samhällsnyttan.","f":0},"18":{"t":"Uppdragsverksamheten sägs vara konkurrensnedvridande och skada förtroendet för myndigheten, alltså verkets anseende.","f":0},"19":{"t":"Två konkreta åtgärder är att expeditionsavgifter höjs medan priserna på den geografiska informationen sänks för ökad användning.","f":0},"20":{"t":"Målen för omstruktureringen uppfylldes med bara ett par undantag; omorganisationen framställs som i grunden lyckad med brister som bör åtgärdas.","f":0},"21":{"t":"Man reser för vidareutbildning med hjälp av pengar man tilldelats, dvs. stipendier.","f":0},"22":{"t":"Ett dokument på 350 sidor är mastigt (omfångsrikt), och en utredning landar i en lång rad rekommendationer.","f":0},"23":{"t":"I skymundan (undanskymt) togs marken i besittning av odlare och förvandlades till en frodig (grönskande) trädgård.","f":0},"24":{"t":"Den som bryter mot reglerna blir ovillkorligt utesluten, dvs. obönhörligen diskvalificerad.","f":0},"25":{"t":"De två grupperna är romantiska fraktioner, och mellan dem rådde (fanns) en rivalitet. Fraktionerna – rådde passar semantiskt och grammatiskt.","f":0},"26":{"t":"Traditionsmat som återkommer år efter år trotsar tidens tand, dvs. står emot att förändras med tiden.","f":0},"27":{"t":"När siffrorna inte räckte intensifierades arbetet med att ta fram inventeringsmetoder som fortfarande används. Metoder tas fram, inte mönster eller stammar.","f":0},"28":{"t":"Omvända samband innebär att det är ovanligare (inte vanligare) att den som rökt eller druckit kaffe får sjukdomen.","f":0},"29":{"t":"Sekretess innebär förbud mot att avslöja en uppgift, dvs. att röja den.","f":0},"30":{"t":"I höga bergsområden kan man uppleva strapatser (mödosamma ansträngningar) och njuta av en vidunderlig (storslagen) utsikt.","f":0}},"v1":{"1":{"t":"Haverera betyder att gå sönder eller förolyckas (t.ex. ett fartyg som havererar). Synonymen är därför 'gå sönder'.","f":0},"2":{"t":"Bestående betyder varaktigt, något som inte försvinner. 'Permanent' fångar just denna varaktighet.","f":0},"3":{"t":"Handräckning betyder bistånd eller assistans som ges åt någon. Synonymen är 'hjälp'.","f":0},"4":{"t":"Sank mark är vattensjuk och blöt. Det motsvaras bäst av 'sumpig'.","f":0},"5":{"t":"Ett mothugg är en skarp motreplik eller invändning mot något. Det ligger nära 'häftig kritik'.","f":0},"6":{"t":"Händelsevis betyder att något sker slumpmässigt, inte planerat. Det motsvaras av 'av en tillfällighet'.","f":0},"7":{"t":"Spänst syftar på kroppens fjädrande kraft, både muskelstyrka och rörlighet. 'Styrka och smidighet' fångar detta.","f":0},"8":{"t":"Porös betyder full av porer så att vätska eller luft kan tränga igenom. Synonymen är 'genomsläpplig'.","f":0},"9":{"t":"Soliditet syftar på ekonomisk styrka och betalningsförmåga. Det motsvaras av 'finansiell stabilitet'.","f":0},"10":{"t":"Målföre betyder talförmåga. Att förlora målföret är alltså att 'bli stum'.","f":0},"11":{"t":"Textens jag uppmanar oss att söka förstå apparaterna och öka vår kunskap, så att de inte längre framstår som fiender. Alltså: med kunskap besegra rädslan inför det främmande.","f":0},"12":{"t":"De enkla redskapen förstår vi och ser som vänner, men den obegripliga chokladapparaten möter vi med främlingskap och ovisshet. Reaktionen bottnar i bristande tillit till det vi inte begriper.","f":0},"13":{"t":"Texten säger att eftersom alla mentala avvikelser ger eller orsakas av spår i hjärnan kan ett neuropsykiatriskt perspektiv läggas på all psykisk sjukdom, oavsett hur den uppstått.","f":0},"14":{"t":"Gruppens majoritet kom från andra områden än psykiatrin och skaffade kunskap via litteratur och hearings. Man valde alltså personer med blandad akademisk bakgrund i förhoppning att de kunde sätta sig in i ämnet.","f":0},"15":{"t":"Författaren invänder att professionen enligt rapporten ska styra forskningen, men medger att Johannisson troligen har rätt i att biologiskt grundad forskning skulle gynnas. Alltså invändning men medgivande.","f":0},"16":{"t":"Seminariets underrubrik 'Bra vård kräver bra psykiatriforskning' visar grundantagandet att kvalificerad forskning förbättrar den psykiatriska vården.","f":0},"17":{"t":"Texten noterar att prästerna kanske tog i överkant i sina rapporter men att resultatet ändå är anmärkningsvärt. Siffrorna bör alltså tolkas med viss försiktighet.","f":0},"18":{"t":"Konventikelplakatet förbjöd folk att läsa Bibeln i grupp utan präst. Det riktades mot läsarnas nya syn att människan själv kan tolka skrifterna utan mellanhand, dvs mot självständiga tolkningar.","f":0},"19":{"t":"Martling-citatet förklarar varför åtgärderna inte gav resultat: de maktägande såg med misstänksamhet på prästernas försök att höja folkbildningen. Det belyser alltså varför kyrkan motarbetades i sina ansträngningar att öka läskunnigheten.","f":0},"20":{"t":"Kyrkan ville skapa lydiga församlingsbor, men läskunnigheten väckte i stället självkänsla och gav stöd åt att ifrågasätta auktoriteter och makten.","f":0},"21":{"t":"Det är 'aktörer' (de inblandade parterna) som ska dela information, och 'insatta' resurser är de som redan tagits i bruk i nödsituationen. Övriga alternativ passar inte semantiskt.","f":0},"22":{"t":"Efter veterinärbehandling behöver hästen tid att återhämta sig, vilket är just 'konvalescens'.","f":0},"23":{"t":"Pausering, betoning och minspel bildar tillsammans 'språkmelodi'. Görs det på ett ovant sätt för 'sammanhanget' missar vi budskapets 'karaktär'. Kedjan hänger ihop.","f":1},"24":{"t":"Att sinande grundvatten till viss del kan 'tillskrivas' mänsklig aktivitet, och en 'betydande' andel av nederbörden fastnar i träden. Sammanhanget kräver dessa ord.","f":0},"25":{"t":"Benfragmenten visade sig 'härröra' från (ha sitt ursprung i) en kollektivgrav. Det är det enda ordet som betyder komma ifrån.","f":0},"26":{"t":"Att allt fler texttyper dyker upp och är olika varandra är 'diversifiering'. Följden är att allt färre råd kan 'generaliseras' från en texttyp till en annan.","f":0},"27":{"t":"Metoden följde 'vedertagen' (allmänt accepterad, etablerad) statistisk teori, vilket förklarar att valet föll sig naturligt.","f":0},"28":{"t":"Nattligt inbrott gör omständigheten starkt 'graverande' (försvårande), brottet var helt 'oprovocerat' och offret kunde inte 'värja sig'. Alla tre passar en juridisk beskrivning.","f":0},"29":{"t":"Missnöjet med EU var inte 'unikt' för Storbritannien, men till skillnad från andra länder finns det där även inom 'etablissemanget', inte bara hos ytterlighetspartier.","f":0},"30":{"t":"Studenterna upplever en 'diskrepans' (skillnad, bristande överensstämmelse) mellan vad de lär sig och vad de förväntas göra i arbetslivet.","f":0}},"q0":{"1":{"t":"12x − 54 = 6x + 18 ger 6x = 72, alltså x = 12.","f":0},"2":{"t":"√3·x = 6 ger x = 6/√3 = 6√3/3 = 2√3.","f":0},"3":{"t":"x/15 + x/30 = 2x/30 + x/30 = 3x/30 = x/10 = 0,1x, dvs 10 % av x.","f":0},"4":{"t":"De tre vinklarna ligger på samma sida om en rät linje och summerar till 180°: (3x+30)+(2x+20)+(x+10)=180 ger 6x=120, x=20°.","f":0},"5":{"t":"Med nämnare 32: 3/4=24/32, 25/32, 13/16=26/32. Alltså 24/32 < 25/32 < 26/32, dvs 3/4 < 25/32 < 13/16.","f":0},"6":{"t":"g(x) = −½·(2x−4) = −x+2. Räta linjen har lutning −1 och skär y-axeln i 2 (och x-axeln i 2) — den fallande linjen genom (0,2).","f":0},"7":{"t":"Diagonalen d = s√2 ger d² = 2s². Då blir 2s² + d² = 2s² + 2s² = 4s² = 64, så s² = 16 och s = 4.","f":0},"8":{"t":"Täljaren: 3(x+y) − 5(y−x) = 3x+3y−5y+5x = 8x−2y. Delat med 2 blir 4x − y.","f":0},"9":{"t":"y = x − 7. Är x negativt blir y = x − 7 ännu mindre än −7, alltså säkert negativt. Övriga påståenden kan brytas.","f":0},"10":{"t":"Punkten (a, 2a) i y = 3x − 60 ger 2a = 3a − 60, alltså a = 60.","f":0},"11":{"t":"Summan i lådorna är 6 (jämnt). Antalet lådor med udda antal måste vara jämnt (0 eller 2) — exakt en är omöjligt, så sannolikheten är 0.","f":0},"12":{"t":"8^x = 2^{3x}, så exponenten måste vara delbar med 3. 16·32 = 2^4·2^5 = 2^9 = 8^3.","f":0},"13":{"t":"√5+1 ≈ 3,24 medan √6 ≈ 2,45. Kvantitet I är större.","f":0},"14":{"t":"x/4 = 5/8 − 1/2 = 1/8, alltså x = 1/2. Kvantitet II (2) är större.","f":0},"15":{"t":"(x+2y) − (2x+y) = y − x > 0 eftersom y > x. Kvantitet I är större.","f":0},"16":{"t":"3/5 − 4/7 = 21/35 − 20/35 = 1/35. Gånger 32 blir 32/35 < 1, så Kvantitet II är större.","f":0},"17":{"t":"Olle får x/2 + y/2 = (x+y)/2. Medelvärdet av Kalles och Pelles ursprungliga antal är också (x+y)/2. Lika.","f":0},"18":{"t":"Med räta vinklar i A och B (koordinater A=(0,0), B=(b,0), D=(0,d), C=(b,c)): I = AD²+AC² = d²+(b²+c²); II = BD²+BC² = (b²+d²)+c². Båda = b²+c²+d², alltså lika.","f":0},"19":{"t":"L: y = −x/2 + 4. Skärning med x-axeln (y=0): x = 8. Skärning med y-axeln: y = 4. Kvantitet I (8) är större.","f":0},"20":{"t":"Medianen = (3:e + 4:e värdet)/2. Dessa ligger i både 'fyra största (>12)' och 'fyra minsta (<15)', så de är 13 eller 14. Medianen kan bli 13, 13,5 eller 14 — otillräckligt mot 13,5.","f":0},"21":{"t":"AB = 2r, AD = r/2, så rektangelns area = r². Halvcirkeln = ½πr² ≈ 1,57r². Rektangel·1,5 = 1,5r². Kvantitet I är större.","f":0},"22":{"t":"x/y = −1 ger x = −y, så x − y = −2y. Tecknet beror på om y är positivt eller negativt — otillräckligt.","f":0},"23":{"t":"(1): 1,25·E = 100 ger E = 80 — räcker. (2): 'en femtedel = 20 %' är alltid sant, ingen information. Alltså (1) men ej (2).","f":0},"24":{"t":"Söker vaniljbullar i frysen. (1) ger 10 vaniljbullar i skafferiet men inte totala antalet vanilj. (2) ger totalt 20 vanilj men inte fördelningen. Tillsammans: 20 − 10 = 10 i frysen.","f":0},"25":{"t":"u+v+w = 180. (1) ger u+v=93, (2) ger u+w=123, var för sig otillräckligt för u. Tillsammans: adderas och kombineras med 180 fås u = 36°.","f":0},"26":{"t":"Totalt 5·172 = 860 cm. (1): flickorna 4·170 = 680, pojken = 860 − 680 = 180 — räcker. (2) ger bara relation till längsta flickan — otillräckligt.","f":0},"27":{"t":"(1) ger bara att vita har kaffe eller te. (2): te i grå och kaffe ej i svart ⇒ kaffe måste vara i vita. Alltså (2) men ej (1).","f":0},"28":{"t":"Delbart med 8 i intervallet 50–75: 56, 64, 72. Ej delbart med 3 tar bort 72, men 56 och 64 återstår båda — otillräckligt även tillsammans.","f":0},"29":{"t":"Frågan gäller fåborstmasken (Oligochaeta), som i diagrammet visas med det ljusgrå fältet - inte det vita fältet som tillhör sandborstmasken. I stapeln för 1982 upptar det ljusgrå fåborstmask-fältet ungefär en tredjedel av stapeln, alltså 1/3 (svar A). Den ursprungliga förklaringen pekar felaktigt ut sandborstmaskens (vita) fält.","f":0},"30":{"t":"Frågan söker året där skillnaden mellan största och näst största artandelen är minst. 2007 domineras av östersjömussla och sandborstmask som är nästan lika stora, minst skillnad.","f":0},"31":{"t":"Sandborstmasken (vit) var liten 1987 (~5 %) men mycket stor 2007 (~40 %), en ökning på ca 35 procentenheter.","f":0},"32":{"t":"Internationell: av 192 elever är 103 sex år (~54 %, drygt hälften) och 88 fem år (~46 %, knappt hälften), nästan inga sjuåringar.","f":0},"33":{"t":"Statlig regi: 42 pojkar av 58 elever = 42/58 ≈ 0,72, alltså 72 procent.","f":0},"34":{"t":"2013/14: 109 943 elever / 3 640 skolenheter ≈ 30 per enhet. 30 − 24 = 6 fler än 2007/08.","f":0},"35":{"t":"I 'Låg'-kolumnen ligger Schweiz punkt närmast 0, alltså minst förändring av andelen i lågkvalificerade yrken.","f":0},"36":{"t":"Räknar länderna som samtidigt har hög-förändring under 5 procentenheter och mellan-förändring under 10 procentenheter i diagrammet; det gäller 5 länder.","f":0},"37":{"t":"Vid OECD-genomsnittet ligger Finland närmast för mellan, Kanada närmast för låg och Ungern närmast för hög.","f":0},"38":{"t":"I flickornas diagram når det understa fältet (psykiska sjukdomar) upp till 50 % första gången år 2011.","f":0},"39":{"t":"Summerar antalet pojkar och flickor för åldrarna 5–10 i det övre diagrammet; det blir sammanlagt ungefär 20 000.","f":0},"40":{"t":"För pojkar 2008 motsvarar fältet för endokrina systemets sjukdomar ungefär 10 % (en tiondel) av de nybeviljade bidragen.","f":0}},"q1":{"1":{"t":"Medelvärdet 7 av fem tal ger summan 5·7=35. De kända talen 1+2+5+7=15, så x=35−15=20.","f":0},"2":{"t":"Elsa startar på 10 och lägger till 3 per dag: K(t)=3t+10. Efter t dagar har hon 10 plus 3 gånger antalet dagar.","f":0},"3":{"t":"Vid x=2: täljaren 2/2=1. Nämnaren 1/2 + 2/(2−1)=1/2+2=5/2. Kvoten 1/(5/2)=2/5.","f":0},"4":{"t":"a+2b=b ger a=−b. Då blir a−b=−b−b=−2b.","f":0},"5":{"t":"Sträckan från T = 90·6=540 km. Avstånd till T: P=245+295=540, Q=155+295=450, R=270+260=530, S=300+260=560. Alltså startade tåget i P.","f":0},"6":{"t":"Punkten ska ligga mellan y=x+2 och y=x−2, dvs x−2<y<x+2. För x=3 krävs 1<y<5. Endast (3,3) uppfyller detta.","f":0},"7":{"t":"Cirkelns area = π·2²=4π. Kvadratens sida = √(area)=√(4π)=2√π cm.","f":0},"8":{"t":"Utveckling: xy+(xb−xy)+(ya−yx)+(ab−ay−xb+xy). Alla xy-, xb- och ay-termer tar ut varandra och kvar blir ab.","f":0},"9":{"t":"10·(3−x)/15 = 2(3−x)/3 = (6−2x)/3. Plus 5x/3 ger (6−2x+5x)/3=(6+3x)/3=2+x.","f":0},"10":{"t":"Förenkla parenteserna: 2√3+3√3=5√3 och 4√3−√3=3√3. Produkt: 5√3·3√3=15·3=45.","f":0},"11":{"t":"Övre rätvinkliga triangeln har kateter x, x, så dess hypotenusa (mittlinjen) är x√2. Nedre rätvinkliga triangeln har kateter x och x√2 samt hypotenusa √3: x²+(x√2)²=3 → 3x²=3 → x=1.","f":0},"12":{"t":"20 % av 10¹⁰ = 0,2·10¹⁰ = 2·10⁹.","f":0},"13":{"t":"I: 1/2−1/3=1/6. II: 2/3−1/2=1/6. Lika stora.","f":0},"14":{"t":"Triangel: 20=½·5·h → h=8. Rektangel: 17=2·h → h=8,5. II (8,5) är större än I (8).","f":0},"15":{"t":"x+2,8=5x−6 → 8,8=4x → x=2,2. I=2,2 är större än II=2.","f":0},"16":{"t":"I: 125 % av 4 = 5. II: 80 % av 6 = 4,8. I är större.","f":0},"17":{"t":"f(−2)=4−4−2=−2. f(0)=0+0−2=−2. Lika.","f":0},"18":{"t":"(47^(x/2))^(2/3)=47^(x/3). Sätt lika med 47^(y/3): x/3=y/3, alltså x=y.","f":0},"19":{"t":"Övre triangeln: 2x+120=180 → x=30. Hela yttre triangeln (bottenvinkel 100°): 2(x+y)+100=180 → x+y=40 → y=10. x=30 är större än y=10.","f":0},"20":{"t":"I=(a−b)²/(a−b)=a−b. II=(b−a)²/(−(a−b))=(a−b)²/(−(a−b))=−(a−b)=b−a. Vilket som är störst beror på om a>b eller a<b, alltså otillräcklig information.","f":0},"21":{"t":"Tid för 120 km: vid 100 km/h=72 min, vid 80 km/h=90 min. Tiden ligger mellan 72 och 90 min, och 85 min ligger inom intervallet, så man kan inte avgöra vilken som är störst.","f":0},"22":{"t":"x+y=2 och (x+4)/2=y ger x+4=2y=2(2−x) → 3x=0 → x=0. I=0 = II=0.","f":0},"23":{"t":"(1): vit<röd och svart varken störst/minst (mitten) → röd störst. (2): svart<röd och vit minst → röd störst. Vardera påståendet räcker var för sig.","f":0},"24":{"t":"(1): mössa 120=150 % av halsduk → halsduk=80, jacka=10·80=800 kr. Räcker. (2): halsduk+mössa=¼ jacka ger bara en relation, jackans pris kan ej bestämmas. Endast (1) räcker.","f":0},"25":{"t":"(1) ger 32 böcker i låda men ej hur många av dem som är romaner. (2) samma problem. Tillsammans vet vi 1121 romaner och 32 i låda, men inte fördelningen romaner/faktaböcker i lådan – går ej att lösa.","f":0},"26":{"t":"Var för sig saknas hastighet respektive avstånd. Tillsammans: samma fart v, Agnes 20 min, Eva 12 min. Skillnad v·(8/60)=2 km → v=15, Agnes=15·(1/3)=5 km. Räcker tillsammans.","f":0},"27":{"t":"Tre olika udda tal med skillnad 4 mellan störst och minst är n, n+2, n+4. Ett känt tal räcker ej. Även x=19 och z=21 tillsammans tillåter både {17,19,21} (summa 57) och {19,21,23} (summa 63) – summan ej entydig.","f":0},"28":{"t":"(1): ringen i grön eller rosa (vit tom). Av rosa och vit är bara en tom = vit, alltså är rosa inte tom → ringen i rosa. Räcker. (2): ger bara att ringen är i grön eller rosa – räcker ej. Endast (1).","f":0},"29":{"t":"Summan för Riksförbundet Hälsofrämjandet 2005–2015: 225+300+300+350+350+350+350+335+300+220+200=3280 tkr.","f":0},"30":{"t":"Friluftsfrämjandet 2015=8600 tkr av summa beviljat 18660 tkr. 8600/18660≈0,46, dvs närmast 45 procent.","f":0},"31":{"t":"Summa beviljat ökade jämfört med föregående redovisat år för 2006, 2007, 2008, 2010, 2011 och 2012 – totalt 6 år (2009, 2013, 2014, 2015 var minskningar).","f":0},"32":{"t":"Metod: sätt cirkelspetsen i mittpunkten av Flenberget, använd skalan (0–15 km) för att markera 5 km radie och räkna fäbodsymbolerna (fyllda kvadrater) inom cirkeln – det blir 8 stycken.","f":1},"33":{"t":"Metod: mät sidorna Mora–Nusnäs–N.Vika med kartans skala och beräkna triangelns area (t.ex. ½·bas·höjd). Ytan blir ca 23 km².","f":1},"34":{"t":"Metod: följ endast ridstigar och buförsvägar (streckade symboler) från Oratjärn/Berg till Björka och mät den kortaste sammanhängande vägen med skalan – ca 18 km.","f":1},"35":{"t":"Läskedrycker/mineralvatten (mittdiagrammet): 2010 ≈100 liter, 1965 ≈25 liter. 100/25=4, alltså fyra gånger så stor.","f":1},"36":{"t":"I nedersta diagrammet skär starköl och vin varandra (ungefär lika) omkring 1985, och där är spritdrycker (ca 6) ungefär hälften av vinkonsumtionen (ca 12).","f":0},"37":{"t":"I översta diagrammet startar standardmjölk kring 115 liter (1960) och slutar kring 20-25 liter (2015). Minskningen blir cirka (115−23)/115 ≈ 0,80, alltså ungefär 80 %. Frågan söker just den dryck som ändrats med 80 %, inte den med störst ändring: gårdsförsäljning faller ännu mer (nära 100 %), medan mellanmjölk och lättmjölk ökar eller varierar. Alltså standardmjölk (D).","f":0},"38":{"t":"Metod: läs av Kalmar läns stapel – den svarta linjen anger kommunen med störst respektive minst genomsnittligt utsläpp. Skillnaden mellan dessa ändpunkter är ca 22 g/km.","f":1},"39":{"t":"Metod: sök länet där (samtliga − bensin/diesel) < 20 g/km OCH kommunens högsta bensin/diesel-värde > 175 g/km. Hallands län uppfyller båda villkoren.","f":1},"40":{"t":"Rikets genomsnitt för samtliga bilar ≈150 g/km. 250620 bilar ·150 g ≈37,6 miljoner g ≈38 ton.","f":0}}},"vt2024":{"v0":{"1":{"t":"En dispyt är en ordväxling eller tvist, alltså ett gräl. Därför är B synonymen.","f":0},"2":{"t":"Angeläget betyder betydelsefullt eller viktigt. E viktigt är synonymen.","f":0},"3":{"t":"Ett supplement är något som läggs till, ett komplement eller tillägg. Därför D tillägg.","f":0},"4":{"t":"Aktad betyder högt värderad och respekterad. A respekterad är synonymen.","f":0},"5":{"t":"Att rata är att välja bort eller avvisa något. Därför B avvisa.","f":0},"6":{"t":"Illa åtgången betyder illa medfaren eller skadad, alltså svårt angripen. D är synonymen.","f":0},"7":{"t":"Bärkraft är förmågan att bära eller hålla över tid, det vill säga hållbarhet. Därför D.","f":0},"8":{"t":"Att vegetera är att leva passivt och overksamt. C leva i overksamhet är synonymen.","f":0},"9":{"t":"Egalitär betyder inriktad på lika värde och lika villkor, alltså jämlik. Därför A.","f":0},"10":{"t":"En kavalkad är en lång följd eller procession, en lång rad. Därför C.","f":0},"11":{"t":"Texten beskriver att vesiklar bildas genom samma avknoppning av cellmembranet men används till olika saker (transport, rengöring, budbärare). Det illustrerar att cellerna använder en och samma process för olika syften. B.","f":0},"12":{"t":"Mossberg testade läkemedel som redan används vid andra sjukdomar. Forskningen pekar alltså mot att redan tillgängliga mediciner kan bli användbara mot vaskulit. C.","f":0},"13":{"t":"Författarna hänvisar till forskning som visar att hotade arter behöver större sammanhängande naturskog. De små, spridda hänsynsytorna är därför alltför utspridda och för små. D.","f":0},"14":{"t":"Kritiken är att virkesproduktionen styrs av starka lagkrav medan naturhänsynen är frivillig, vilket ger obalans mellan skogsnäringens och naturvårdens intressen. B.","f":0},"15":{"t":"Huvudproblemet enligt författarna är avverkningsmetoderna (kalhyggen, schablonhänsyn) som allvarligt skadar den biologiska mångfalden. C.","f":0},"16":{"t":"Avslutningen kräver att skogsindustrins monopol bryts och att ett gemensamt samhällsansvar tas, det vill säga att skogsbolagens makt begränsas och andra samhällsintressen ges plats. D.","f":0},"17":{"t":"Tommy minns morfadern varmt (dansen, skokrämsgitarren) och stör sig på prästens opersonliga tal; han känner att begravningen inte gör morfadern rättvisa. C.","f":0},"18":{"t":"Modern rättar till filten, dirigerar och bestämmer detaljer som skorna. Hon framstår som dominant och petig med detaljer. B.","f":0},"19":{"t":"Bara den närmaste familjen är där, det finns ingen musik och prästen framstår som opersonlig. Det passar bäst med en enkel ceremoni med opersonlig präst. A.","f":0},"20":{"t":"Efter ceremonin riktas Tommys tankar mot flamman Gun; han undrar över henne och känner sig bekant med henne. Rimligast är att han är nyfiken på Gun. A.","f":0},"21":{"t":"Att berättelserna tycks vara självbiografiskt förankrade betyder att de har grund i författarens eget liv. D förankrade passar.","f":0},"22":{"t":"Innehållet ska baseras på relevanta data, och planen är ett verktyg för att involvera de lokala aktörerna och fånga medborgarperspektivet. C data - involvera.","f":0},"23":{"t":"Förslaget till restaurering utgick från förutsättningarna och tog fasta på möjligheter till återställande och bevarande. B ger en logisk och samstämmig mening.","f":0},"24":{"t":"Hur en röst ter sig akustiskt varierar, därför är det svårt att hitta objektiva kriterier för röststatus. A ter sig - kriterier.","f":0},"25":{"t":"Att nästan alla lärde sig läsa, skriva och räkna var ovärderligt (oerhört värdefullt) för modernitetsbygget. C.","f":0},"26":{"t":"Innan resan kunde återupptas måste fartyget repareras, en reparation som tog två månader i anspråk. B återupptas - i anspråk.","f":0},"27":{"t":"Pethrus symboliska kapital var så starkt att han personligen förkroppsligade rörelsen, det vill säga utgjorde dess konkreta gestalt. D.","f":0},"28":{"t":"Varje språk uttrycker en egen världsbild och lägger ett raster över verkligheten, som därmed inte avbildas utan tolkas. B world-bild - raster - tolkas.","f":0},"29":{"t":"Kunskap vi kan formulera är explicit; vardagskunskap som inte kan formuleras är implicit eller tyst kunskap. C explicit - implicit.","f":0},"30":{"t":"Luttrad betyder härdad av erfarenhet; Baltimore-borna hade av bitter vana väntat sig ännu ett frikännande. A luttrat.","f":0}},"v1":{"1":{"t":"Att försegla betyder att sluta till eller täta något, alltså tillsluta.","f":0},"2":{"t":"En autodidakt har lärt sig något på egen hand utan formell utbildning, alltså en självlärd person.","f":0},"3":{"t":"Gentemot uttrycker en relation eller jämförelse, dvs. i förhållande till.","f":0},"4":{"t":"Utarmad betyder att något tömts på resurser eller näring, alltså blivit fattig.","f":0},"5":{"t":"Ett axplock är ett litet, ganska godtyckligt sammanplockat urval, alltså ett slumpartat urval.","f":0},"6":{"t":"Exceptionell betyder ovanlig i betydelsen att den förekommer sällan, alltså sällsynt.","f":0},"7":{"t":"Att tillkännage betyder att offentligt göra känt eller meddela något.","f":0},"8":{"t":"En appell är en enträgen uppmaning eller vädjan riktad till någon.","f":0},"9":{"t":"Intrikat beskriver något komplicerat och svåröverskådligt, alltså invecklat.","f":0},"10":{"t":"Debacle betyder ett stort nederlag eller fiasko, alltså ett misslyckande.","f":0},"11":{"t":"NN förklarade problemen med en kraftig anhopning av arbets- och utvecklingsuppgifter för honom personligen, vilket gav eftersläpningar. Alltså att arbetsbördan varit för stor.","f":0},"12":{"t":"Nämnden framhöll som särskilt anmärkningsvärt att en redovisningskonsult inte följt bestämmelserna i sitt eget bolag, dvs. brustit inom sitt eget yrkesområde.","f":0},"13":{"t":"Textförfattaren menar att det vetenskapliga skrivsättets konventioner distanserar och stänger läsaren ute, dvs. att stilkraven begränsar förmågan att kommunicera med omvärlden.","f":0},"14":{"t":"Den 'virtuella akademikern' beskrivs ironiskt som en tjänst som slumpar ihop tomma modeord, alltså ett humoristiskt men avskräckande exempel på akademiskt språk.","f":0},"15":{"t":"Författaren ifrågasätter den etablerade sanningen att vetenskaplighet kräver opersonlighet och objektivitet, dvs. att riktig vetenskap skulle utesluta ett subjektivt förhållningssätt.","f":0},"16":{"t":"Nicholsons bok visar hur det verkligt upplevda förmedlas bättre än torr statistik, vilket illustrerar essäns förmåga till konkretion.","f":0},"17":{"t":"De nyskrivna skådespelen och teatern skapade behov av rekvisita, kläder och varor som de nya yrkena tillgodosåg.","f":0},"18":{"t":"Tidens ideal, präglat av protestantisk syn, föraktade det konstlade och tillgjorda, vilket gjorde skådespeleri och de nya yrkena ifrågasatta.","f":0},"19":{"t":"Skådespelarna använde professionaliseringsstrategier för att markera sin olikhet gentemot de framgångsrika kvinnorna kring teatern.","f":0},"20":{"t":"En central poäng är att teaterlivet var beroende av kvinnors arbete, som sedan doldes och osynliggjordes i historieskrivningen.","f":0},"21":{"t":"Jättepandan lever nästan bara av bambu; uteslutande betyder 'endast', vilket passar med 'nästan'.","f":0},"22":{"t":"En ändamålsenlig försöksverksamhet ska komma till stånd (bli av) utan att regelverket lägger hinder i vägen.","f":0},"23":{"t":"Läkemedel har baserats på naturprodukter men framställs numera syntetiskt, och kan utgå från en naturlig substans som modifieras.","f":0},"24":{"t":"Trots beslutsångesten hjälpte butiksinnehavarens råd föga, dvs. nästan inte alls.","f":0},"25":{"t":"Byggnaden är anpassad till topografin (terrängen) och smyger sig upp i slänten; storleken blir därför märkbar först vid entrén.","f":0},"26":{"t":"PISA används som tillhygge för att argumentera politiskt, dvs. har blivit ett slagträ i debatten.","f":0},"27":{"t":"Fysiken beskriver enbart objektivt mätbara egenskaper, medan hjärnan rymmer subjektiva upplevelser tillgängliga bara inifrån. Kontrasten objektivt/subjektiva passar.","f":0},"28":{"t":"Liberalismen är fast rotad i rättigheter: rätten till personlig integritet och rätten att bekänna sig till den religion man föredrar.","f":0},"29":{"t":"Grön starr heter glaukom på medicinskt språk och upptäcks vid ögonbottenfotografering.","f":0},"30":{"t":"Idéerna orsakade ramaskri (högljudda protester) bland partiets gräsrötter (vanliga medlemmar) och fick därför tonas ner.","f":0}},"q0":{"1":{"t":"Kvadratens area 16 ger sidan 4. Triangeln ovanpå har area 6 med basen 4, så dess höjd = 2·6/4 = 3. Sträckan x = kvadratens sida + triangelns höjd = 4 + 3 = 7 cm.","f":0},"2":{"t":"Sätt in y = −2: 2x + 3x(−2) − 4(−2) = 2x − 6x + 8 = −4x + 8 = 10. Då blir −4x = 2, alltså x = −1/2.","f":0},"3":{"t":"f(x)=x/2−1 har positiv lutning (1/2) och skär y-axeln i −1 samt x-axeln i x=2. Bara graf D är svagt stigande och passerar under origo på det sättet.","f":0},"4":{"t":"0,6·x = 39 ger x = 39/0,6 = 65.","f":0},"5":{"t":"Utveckla: ab+ac − ab−bc + cb−ca = (ab−ab)+(ac−ca)+(−bc+cb) = 0.","f":0},"6":{"t":"Linjen från B delar triangeln. Vid punkten på AC är vinkeln mot C 180−123=57°. I triangeln med C: 65°+57° ger den tredje vinkeln 58° vid B. Eftersom hela vinkeln vid B är rät (90°) blir x = 90−58 = 32°.","f":0},"7":{"t":"Med a>0, b<0: x-koordinaten a²b är (positiv)·(negativ)=negativ, och y-koordinaten ab³ är (positiv)·(negativ)=negativ. Båda negativa = tredje kvadranten, dvs punkt R.","f":0},"8":{"t":"Klossarna passar jämnt: 50/5=10, 54/6=9, 72/9=8. Antal = 10·9·8 = 720.","f":0},"9":{"t":"2xy(3xy+15y)/(6xy²) = 2xy·3y(x+5)/(6xy²) = 6xy²(x+5)/(6xy²) = x+5.","f":0},"10":{"t":"Heltal 0<x<y<z med xyz=12. Uppdelningen 1·2·6 ger z−x = 6−1 = 5, vilket är störst (jfr 1·3·4 som ger 3).","f":0},"11":{"t":"Låda A (2R,1V) måste tappa en röd för att bli 1R1V: sannolikhet 2/3. Låda B (1R,2V) måste tappa en vit: 2/3. Då hamnar en röd och en vit i C automatiskt. Svar = 2/3·2/3 = 4/9.","f":0},"12":{"t":"2(2⁵+2⁵) = 2·(2·2⁵) = 2·2⁶ = 2⁷.","f":0},"13":{"t":"Med y=0 blir x−5 = 0+5, alltså x=10. Kvantitet I=10 > Kvantitet II=0.","f":0},"14":{"t":"Nionde jämna talet efter 15: 16,18,…,32 → J=32. Sjunde udda talet efter 18: 19,21,…,31 → U=31. J−U = 1 > 0.","f":0},"15":{"t":"Medelvärdet av 1/10 och 1/5 = (0,1+0,2)/2 = 0,15. Kvantitet II = 1/7 ≈ 0,143. 0,15 > 0,143.","f":0},"16":{"t":"a≤−1 och b<0 ger a/b>0, men storleken varierar: a=−1,b=−0,5 ger 2 (>1); a=−1,b=−2 ger 0,5 (<1). Informationen räcker inte.","f":0},"17":{"t":"Sidan = 75/5 = 15. AB och ED är sidor (15+15=30), BE är en diagonal ≈ 15·1,618 ≈ 24. Summan ≈ 54 > 45.","f":0},"18":{"t":"I: 50 % av tal >1000 ger >500 (kan bli hur stort som helst). II: 75 % av tal <800 ger <600. De kan överlappa åt båda håll, så otillräckligt.","f":0},"19":{"t":"x/3 = 1 − 3/2 = −1/2, alltså x = −3/2 ≈ −1,5. Kvantitet II = −1/6 ≈ −0,17. Eftersom −1,5 < −0,17 är II större.","f":0},"20":{"t":"L1 lutning = (2−3)/(1−(−1)) = −1/2. L2 vinkelrät ger lutning = 2. Kvantitet II (2) > Kvantitet I (−1/2).","f":0},"21":{"t":"Triangeln 3,4,5: omkrets 12, area = 3·4/2 = 6. Kvadraten med samma omkrets har sidan 3 och area 9. II (9) > I (6).","f":0},"22":{"t":"I = (x⁴+1)·x(x²−1). II = x(x⁴+1)·(x²−1). Båda blir x(x²−1)(x⁴+1) – identiska uttryck, alltså lika.","f":0},"23":{"t":"(1) x≥3 och (2) x≤4 ger tillsammans x=3 eller 4 – inte ett entydigt värde. Varken var för sig eller tillsammans räcker.","f":0},"24":{"t":"(1) ger total 792 och största 348, men inte de övriga. (2) säger att mellanboken = medelvärdet. Tillsammans: medel = 792/3 = 264 = mellanboken, minsta = 792−348−264 = 180. Krävs båda.","f":0},"25":{"t":"Tillsammans: paljetter i svarta, knappar i röda, och pärlor+limstift i blå/grå (i någon ordning). Men vilken av blå och grå som har limstift går inte att avgöra. Otillräckligt.","f":0},"26":{"t":"Facit är D (vardera påståendet räcker ensamt), inte C. Sträckan L är samma varje runda, så L = v·t. (1): lägsta farten hör ihop med längsta tiden och högsta farten med kortaste tiden: 15 km/h·(20/60 h) = 5 km och 25 km/h·(12/60 h) = 5 km – båda ger L = 5 km, alltså räcker (1) ensamt. (2): medelhastigheten = total sträcka/total tid, så total sträcka = 20·(75/60) = 25 km och en runda = 25/5 = 5 km – (2) räcker också ensamt. Därför D.","f":0},"27":{"t":"Tillsammans: 12 stora, varav 9 röda och 3 gröna; små = 48−12 = 36, varav 13 gröna (från 1) ger 23 små röda. Totalt röda = 9+23 = 32. Krävs båda.","f":0},"28":{"t":"Svaret B (endast (2) räcker) är rätt, men förklaringen är motsägelsefull – den påstår att svart hamnar längst till höger, vilket är fel. Med (2): röd står längst till vänster (plats 1); efter att svart och vit bytt plats ska vit ligga mitt emellan röd och grön, dvs röd–vit–grön på plats 1–2–3, vilket betyder att före bytet var ordningen röd, svart, grön, vit. Alltså är vit längst till höger, och ordningen är entydig → (2) räcker ensamt. (1) ensamt ger två möjliga ordningar (längst till höger blir antingen röd eller vit) och räcker inte. Svar B.","f":0},"29":{"t":"Storstäder och Kommuner i tätbefolkad region har de bar-par (grå = antal ankomster och svart = genomsnittlig försening) som ligger närmast varandra på båda skalorna samtidigt.","f":1},"30":{"t":"Den grå stapeln (antal ankomster) för Förortskommuner är ungefär dubbelt så lång som för Större städer, alltså dubbelt så många.","f":0},"31":{"t":"Total förseningstid = antal ankomster · genomsnittlig försening för Kommuner i glesbefolkad region, vilket ger ca 330 000 minuter.","f":0},"32":{"t":"2012 var summorna ca 15 000 (opererande), 12 000 (invärtesmedicinska) och 3 000 (barnmedicinska) – förhållandet ≈ 5:4:1.","f":0},"33":{"t":"Störst 2011 var Internmedicin (5 603), Kardiologi (1 388) och Geriatrik (1 143), summa 8 134 av totalt 11 099 ≈ 73 %, dvs ca 75 %.","f":0},"34":{"t":"Antal 65+ = totalen minus \"därav <65\". För Kirurgi 2010: 3 046−2 029 = 1 017, vilket är flest av de opererande specialiteterna.","f":0},"35":{"t":"Inom Västerort = 19 173, från Söderort till Västerort = 3 148. 19 173/3 148 ≈ 6, alltså sex gånger så stort.","f":0},"36":{"t":"Inom Stockholms kommun = 104 665. Till kommunen = 16 483+20 587+32 668 = 69 738. Skillnad = 104 665−69 738 = 34 927.","f":0},"37":{"t":"Till Söderort (3 148+7 986+24 799 = 35 933) minus från Söderort (3 167+6 406+23 832 = 33 405) = +2 528.","f":0},"38":{"t":"I andelsdiagrammet ökade Får och lamm mest: från ca 14 % (2009) till ca 22 % (2015), dvs ca 8 procentenheter.","f":0},"39":{"t":"2014: svin ca 4 000 ton, får/lamm ca 1 100, kyckling ca 500, nötkreatur ca 19 000. Svin/total = 4 000/≈24 600 ≈ 1/6.","f":0},"40":{"t":"Ekologiskt får/lamm 2012 ≈ 1 000 ton och utgjorde ca 20 % av totalen. Total = 1 000/0,20 ≈ 5 000 ton.","f":0}},"q1":{"1":{"t":"4x+13=8x-31 ger 13+31=8x-4x, dvs 44=4x, så x=11.","f":0},"2":{"t":"Linjen har lutning -3 och skär y-axeln vid -2, dvs y=-3x-2. Endast (1,-5) stämmer: -3·1-2=-5.","f":0},"3":{"t":"1/2+1/6=3/6+1/6=4/6=2/3. Sedan 1/3-2/3=-1/3.","f":0},"4":{"t":"Medel(17,21,44)=82/3. Sätt lika: (63+73+x)/3=82/3 ger 136+x=82, x=-54.","f":0},"5":{"t":"Julias fart 2km/12min=1/6 km/min, Annas 2km/24min=1/12. Tillsammans 1/6+1/12=1/4 km/min. Tid=12/(1/4)=48 min.","f":0},"6":{"t":"(7/√7)^2=49/7=7. (Övriga: A≈9,9; B=6; C=5,5.)","f":0},"7":{"t":"18% av 2/5 = 0,18·2/5 = 36/500 = 9/125.","f":0},"8":{"t":"Kvadratens area 4²=16. M är hörn och cirkelns medelpunkt (r=2), så en kvartscirkel ligger inne i kvadraten: (1/4)π·2²=π. Skuggat=16-π.","f":0},"9":{"t":"Sätt in (3,1): y=-x+4 ger 1=-3+4=1, stämmer.","f":0},"10":{"t":"a/b=b/c ger b²=ac. Med c=2a: b²=2a², så b=a√2.","f":0},"11":{"t":"x·10⁴-2x·10³=10000x-2000x=8000x=32000, så x=4.","f":0},"12":{"t":"K1 area=2²=4. 25% av K1 = 20% av K2: 0,25·4=1=0,20·area(K2), så area(K2)=5, sida=√5.","f":0},"13":{"t":"3x>y ger inget entydigt om x mot y. Ex x=1,y=1 ger I=II; x=1,y=2 ger I<II. Otillräckligt.","f":0},"14":{"t":"Den vita triangeln förbinder varannat hörn i sexhörningen och utgör exakt halva arean. Skuggat = ej skuggat = 1/2.","f":0},"15":{"t":"2(x-4)=1/2 ger x-4=1/4, x=4,25. Det är mindre än 5, så II>I.","f":0},"16":{"t":"f(a)=4a+8. g(2a)=2·2a+4=4a+4. Eftersom a>0 saknar det betydelse: 4a+8>4a+4, alltså I>II.","f":0},"17":{"t":"Median av 10 tal=(5:e+6:e)/2=25. Tar man bort största och minsta blir det 8 tal vars median = (nya 4:e+5:e)= samma 5:e och 6:e talen, så medianen förblir 25.","f":0},"18":{"t":"4·10⁻²=0,04=1/25, medan II=1/400. 1/25>1/400, så I>II.","f":0},"19":{"t":"x negativt, y positivt. Kvoterna är negativa men storleken beror på värdena: x=-0,5,y=0,9 ger II>I; x=-0,9,y=0,5 ger I>II. Otillräckligt.","f":0},"20":{"t":"Sidan AD lutar 70° mot L2 (eftersom AB∥DC lutar 20° och hörnet är rätt). Så x=70°, och x-50=20°=I. Lika.","f":0},"21":{"t":"I=x²+2x-8, II=x²-2x-8, så I-II=4x. Med x<0 är 4x<0, alltså I<II, dvs II>I.","f":0},"22":{"t":"Fördubbling: 1,2^t=2 ger t=ln2/ln1,2≈3,8 år, vilket är mindre än 5 år. Så II>I.","f":0},"23":{"t":"(1) apotek före bibliotek; (2) cykelhandlaren är näst (mitten). Var för sig otillräckligt, men tillsammans: cykel=2:a, apotek=1:a, bibliotek=3:a. Krävs båda.","f":0},"24":{"t":"Figurens yttervinkel 130° ger v=50°. (1) w=65° ger u=180-65-50=65°, tillräckligt. (2) v=50° är redan känt från figuren och räcker inte utan w.","f":0},"25":{"t":"Tanken är 4/7 full. (1) 3/7·V=1200 ger V=2800. (2) 4/7·V-200=1/2·V ger (1/14)V=200, V=2800. Var för sig tillräckligt.","f":0},"26":{"t":"Var för sig saknas absolut antal udda. Tillsammans: (1) 150 jämna, 40% öst-västligt=60 jämna öst-västligt; (2) lika många udda som jämna öst-västligt=60, och det är 1/3 av alla udda, så udda=180. Krävs båda.","f":0},"27":{"t":"(1) A+100=3A ger 2A=100, A=50 – tillräckligt. (2) blandar in Berit med två obekanta – otillräckligt.","f":0},"28":{"t":"Tillsammans: w=x+y och z=(x+y)/2=w/2. Vilket av x,y,z,w som är störst beror på tecken/storlek (t.ex. x=y=1 ger w störst; x=10,y=-1 ger x störst). Ej ens med båda.","f":0},"29":{"t":"Fritidsresor utrikes (mörka bandet) utgör störst andel av det totala antalet resor år 2016, då totalen minskat men det mörka bandet fortfarande dominerar.","f":0},"30":{"t":"Mellan 2012 och 2013 minskade totalen, men bandet för Affärsresor inrikes blev tjockare – det var den enda kategori som ökade.","f":0},"31":{"t":"År 2016 utgör utrikesresorna (affärs+fritid utrikes) ca 35% och inrikesresorna ca 65% av totalen.","f":0},"32":{"t":"En femtedel av 503 ≈101. El (84) + Vindkraftverk (16) = 100 ≈ 1/5.","f":1},"33":{"t":"I juni är totalen ca 39, varav okänd (svart) ca 24 och känd ca 15. Förhållandet okänd:känd = 24:15 = 8:5.","f":0},"34":{"t":"Totalt inkomna 503 (cirkeldiagram); med angiven fyndmånad 414 (stapeldiagram). 414/503≈0,82=82%.","f":0},"35":{"t":"Gävleborg 2015: summa i sektorn 4434, därav jordbruk 1774. 1774/4434≈0,40=40%.","f":0},"36":{"t":"Störst andel av totala förvärvsarbetande (kolumnen Samtliga) har Gotland, 6,44%. Sektorns summa där=1744, så totalt=1744/0,0644≈27000.","f":0},"37":{"t":"Var femte=20% kvinnor i sektorn. Kalmar: 1055/4965≈0,21≈1/5, närmast bland alternativen.","f":0},"38":{"t":"Sökt gård har boningshus/stuga norr om gårdsplanen och stall+stallslider söder om den. Det stämmer med Kockgård (E).","f":0},"39":{"t":"Torvhuset (nr 20) mellan nordöstra Stamgården och Ryssgård intill en stuga; 40 m rakt söder därom (via skalan) ligger ett loft (nr 4).","f":0},"40":{"t":"Triangeln med hörn i fähusen i Måsgård, Ammagård och sydligaste fähuset i Jerkgård har med kartskalan en area på ca 6500 m².","f":0}}},"ht2023":{"v0":{"1":{"t":"'Proper' betyder prydlig, snygg och välskött - alltså 'välvårdad'.","f":0},"2":{"t":"En galosch är ett överdrag av gummi som man drar på skon - alltså en 'gummisko'.","f":0},"3":{"t":"Att dementera betyder att tillbakavisa eller ta avstånd från ett påstående - alltså 'förneka'.","f":0},"4":{"t":"'Medaljens baksida' är ett uttryck för den negativa sidan av något positivt - alltså 'nackdelen'.","f":0},"5":{"t":"Cerebral kommer av latinets cerebrum (hjärna) och betyder 'som gäller hjärnan'.","f":0},"6":{"t":"En hemsökelse är en återkommande olycka eller plåga som drabbar många - alltså 'utbredd plåga'.","f":0},"7":{"t":"Tjänlig betyder lämplig eller duglig att använda för ett ändamål - alltså 'användbar'.","f":0},"8":{"t":"Att vara avhängig av något betyder att vara beroende av det - alltså 'bero på'.","f":0},"9":{"t":"Klander är kritik eller tillrättavisning - alltså en 'ogillande anmärkning'.","f":0},"10":{"t":"Omsorgsfull betyder att göra något med omsorg och noga - alltså 'noggrann'.","f":0},"11":{"t":"Kärnan i tvisten var att Transportstyrelsen ansåg att rapporten inte var ett beslut, medan förvaltningsrätten (efter kommunens överklagan) menade att den skulle uppfattas som ett beslut. Oenigheten gällde alltså hur rapporten skulle uppfattas.","f":0},"12":{"t":"Förvaltningsrätten går emot Transportstyrelsen på i stort sett alla punkter och river upp myndighetens ställningstagande. Kommunen (Falu kommun/Klarbo) får rätt och kan därmed betraktas som vinnare.","f":0},"13":{"t":"Texten förklarar att en inlärd koppling mellan nedstämdhet och negativt tänkande finns kvar efter tillfrisknandet, så att invanda tankebanor lätt aktiverar och förstärker även svag nedstämdhet och triggar igång depressionen igen.","f":0},"14":{"t":"MBKT beskrivs som förebyggande kognitiv terapi som bygger vidare på den traditionella kognitiva psykoterapin - alltså en vidareutveckling av en redan etablerad metod.","f":0},"15":{"t":"MBKT handlar om att bli medveten om sina mentala växlingslägen ('doing mode'/'being mode') och att kunna känna igen och byta mellan dem - alltså att uppmärksamma sitt eget mentala förhållningssätt och även kunna bryta det.","f":0},"16":{"t":"Studien visade bäst effekt för patienter med tre eller flera tidigare depressioner, där återfallen blivit mer automatiserade och självgående - då svarar MBKT väl mot behovet.","f":0},"17":{"t":"Östling använder den historiska tillbakablicken för att belysa och skapa perspektiv på universitetets situation och utmaningar i dag, inte främst för att öka kunskap om historien i sig.","f":0},"18":{"t":"'Culture war' illustreras genom Bloom (som förordade västerländska klassiker) mot Nussbaum (som ville bredda pensum till det främmande). Striden gällde alltså vilka texter som ska läsas.","f":0},"19":{"t":"Enligt texten saknade Newman en utvecklad tanke om forskningens roll, medan Humboldt framhävde forskningen och den akademiska friheten. Humboldt betonar alltså till skillnad från Newman den oberoende forskningen.","f":0},"20":{"t":"Östling ser risken att universiteten dras in i global konkurrens och att ämnen bedöms efter ekonomisk nytta - alltså att verksamheten riskerar att styras av ekonomiska hänsynstaganden.","f":0},"21":{"t":"Syntetfibrer framställs i kemiska processer som kan jämföras med (sättas lika med) plasttillverkning - 'likställas' passar.","f":0},"22":{"t":"Turiststrommar går till historiska 'monument', och människor har i alla tider 'uppskattat' arkitektur - båda leden passar semantiskt.","f":0},"23":{"t":"Vi ser 'sammanhang' och kategorier, det styr hur vi värderar 'information', och nya fakta fogas till vår 'förförståelse' av världen - alla tre led hänger logiskt ihop.","f":0},"24":{"t":"Reciprocitet betyder ömsesidighet, alltså att länderna 'ömsesidigt' förbinder sig att avveckla handelshinder.","f":0},"25":{"t":"Prästen 'antar' en djupsinnig min (att anta en min), och han är inte så 'bevandrad' i Dostojevskij (väl insatt) - därav frågan tillbaka.","f":0},"26":{"t":"Kontrasten är att äldre vård bara höll patienten vid liv, medan 1700-talets lasarett även väntade förbättring - alltså 'livsuppehållande' vård.","f":0},"27":{"t":"Snigarnas 'frosseri' (deras ätande) orsakade förlusten, som trots allt var förhållandevis 'måttlig' - liten ekonomisk skada.","f":0},"28":{"t":"Lång tid har 'förflutit' sedan dramat, alla parter 'befann sig' under press, och det är omöjligt att 'utröna' vad som skedde - alla tre led passar.","f":0},"29":{"t":"Nya 'ekipage' (häst och förare) samlades inför det 'förestående' (kommande) loppet - passar tävlingssammanhanget.","f":0},"30":{"t":"I avsaknad av riktlinjer och med prov utformade av lärarna själva var lärarna relativt 'autonoma' (självstyrande) i sin bedömning.","f":0}},"v1":{"1":{"t":"Att löpa amok betyder att gripas av okontrollerat, våldsamt raseri och rusa fram. Det motsvarar 'få raserianfall'.","f":0},"2":{"t":"Påtaglig betyder tydlig, kännbar och lätt att lägga märke till. Synonymen är 'märkbar'.","f":0},"3":{"t":"Uppsåtligen betyder att något görs med avsikt, med berått mod. Det motsvarar 'med avsikt'.","f":0},"4":{"t":"En biopsi är ett medicinskt prov där man tar ut en bit vävnad för undersökning. Alltså 'vävnadsprov'.","f":0},"5":{"t":"Detronisera betyder att störta någon från tronen eller från sin maktställning. Det motsvarar 'avsätta'.","f":0},"6":{"t":"Fruktlös betyder resultatlös, förgäves - ansträngningen bär ingen frukt. Alltså 'som inte ger resultat'.","f":0},"7":{"t":"Kvintessensen är själva kärnan eller det mest väsentliga i något. Det motsvarar 'det väsentliga'.","f":0},"8":{"t":"Enveten betyder envis och ihärdig, någon som inte ger sig. Synonymen är 'envis'.","f":0},"9":{"t":"Ombesörja betyder att se till att något blir gjort, att sköta eller ordna en sak. Alltså 'ordna'.","f":0},"10":{"t":"En ingivelse är en plötslig inre impuls eller inspiration att göra något. Det motsvarar 'plötslig impuls'.","f":0},"11":{"t":"Jaget avundas Gunnar det ständigt nya och överraskande i tillvaron tack vare tresekundersminnet. Det jaget vill undvika är motsatsen: att livet blir förutsägbart.","f":0},"12":{"t":"Det som plågade Mattis mest var tanken på Gunnars torftiga liv och hur få glädjeämnen fisken haft. Alltså tanken på hur fattigt på glädje Gunnars liv varit.","f":0},"13":{"t":"Theanders syfte var att bestrida förenklade föreställningar och visa flickbokens bredd med aktiva, yrkesarbetande kvinnor - alltså att ge en mer nyanserad bild av hur kvinnor framställdes.","f":0},"14":{"t":"Recensenten framhåller värdet av att Theander gått igenom och sammanställt ett stort primärmaterial som bara finns i fysisk form på bibliotekens magasin.","f":0},"15":{"t":"Eftersom översatta verk kan vara gamla eller utländska tvivlar recensenten på om de speglar rätt tidsperiod. Utan dem hade man sluppit undra om texterna verkligen representerar perioden.","f":0},"16":{"t":"Recensenten menar att Året Runt riktade sig till hemmafruar, inte unga flickor, och att Theander därför felaktigt behandlar tidningen som om innehållet vore representativt för tiden ('blanda äpplen och päron').","f":0},"17":{"t":"Det mest uppseendeväckande är att myrorna samarbetar fredligt över släktgränserna och tycks agera osjälviskt mot icke-släktingar, vilket går emot evolutionens grundregel om egennytta.","f":0},"18":{"t":"Att två arter får fertil (fruktsam) avkomma strider mot den traditionella skolboksdefinitionen av art, där korsningar som mulåsnan blir sterila.","f":0},"19":{"t":"Forskarna tror inte systemet är stabilt och betonar att om beteendet inte gynnar de egna släktingarna överlever det inte i längden - de tvivlar alltså på att superkolonier säkrar de egna genernas överlevnad.","f":0},"20":{"t":"Jonna Kulmuni säger att man inte kan veta om detta är början eller slutet för en art och att det är spännande att se artbildningen pågå - alltså att myrorna är i en oförutsägbar evolutionär process.","f":0},"21":{"t":"Meningen kräver att om ingen 'överklagar' valet av leverantör kan leveranserna ske i tid. Att överklaga ett upphandlingsbeslut skulle annars försena processen.","f":0},"22":{"t":"Hornprydda hjälmar är en 'myt' eftersom vi vet att det inte stämmer, och inga källor eller fynd 'vittnar' om (bekräftar) krigare med horn. Både myt och vittnar passar innehållet bäst.","f":0},"23":{"t":"Det fanns en 'utbredd' uppfattning; att snabbt lära språk troddes vara 'förbehållet' (reserverat för) barn; men det finns inga 'kognitiva' (tankemässiga) hinder för vuxna. Alla tre orden matchar.","f":0},"24":{"t":"Att förträngningen är fullt 'reversibel' betyder just att den kan gå tillbaka till normal funktion, vilket förklaras direkt efter luckan.","f":0},"25":{"t":"Svamparna uppfattar att vintern är 'i antågande' (på väg) och börjar bilda fruktkroppar; sporerna kan liknas vid svamparnas 'frön' (spridningsenheter). Båda orden passar.","f":0},"26":{"t":"Uttrycket 'hyllorna bågnar av böcker' betyder att de böjs eller sviktar av tyngden av alla böcker, dvs. det finns gott om dem.","f":0},"27":{"t":"Musikdramatikens 'libretton' är just själva texterna, och dessa kunde vara riktigt 'grovkorniga', rentav vulgära. Båda orden stämmer med sammanhanget.","f":0},"28":{"t":"Lärarcentrerad undervisning kallas 'katederundervisning'; de två synsätten ses som 'ytterligheter'; god undervisning är en väl 'avvägd' blandning. Alla tre orden passar.","f":0},"29":{"t":"Grafen kan tänjas ut utan 'kvarstående' deformation, dvs. utan att formförändringen blir bestående efteråt.","f":0},"30":{"t":"Nobel var 'diffus' (obestämd) om vem som skulle förvalta fonden, men desto mer 'explicit' (tydlig) om vad som skulle belönas. Orden speglar motsatsen obestämd/tydlig i meningen.","f":0}},"q0":{"1":{"t":"Gemensam nämnare 21: 14/21 + 12/21 − 5/21 = 21/21 = 1.","f":0},"2":{"t":"Vinklarna 1:2:6 ger delarna x+2x+6x = 9x = 180°, så x = 20°. Största vinkeln = 6·20° = 120°.","f":0},"3":{"t":"Sätt in x = −2: (−2)³ + b·(−2) − 4 = 0 → −8 − 2b − 4 = 0 → −2b = 12 → b = −6.","f":0},"4":{"t":"3x/4 − 1/2 = 0 → 3x/4 = 1/2 → x = (1/2)·(4/3) = 2/3.","f":0},"5":{"t":"x = 5/8 − 3/5. Gemensam nämnare 40: 25/40 − 24/40 = 1/40.","f":0},"6":{"t":"Medel av x,y = 16 → x+y = 32. Medel av 20,z = 30 → 20+z = 60 → z = 40. Summan = 32 + 40 = 72.","f":0},"7":{"t":"−5x(7 − 3y) = −35x + 15xy = 15xy − 35x = (15y − 35)x.","f":0},"8":{"t":"Sökt största k·m. A: k>0, m=0 → 0. B: k=0 → 0. D: k<0, m>0 → negativ. C har negativ lutning OCH negativt m-värde (linjen skär y-axeln under origo), så k·m blir positiv och därmed störst.","f":0},"9":{"t":"0,10·20 = 0,08·y → 2 = 0,08y → y = 2/0,08 = 25.","f":0},"10":{"t":"Kvadratens area = s². Rektangel: 0,7s · L = s² → L = s²/(0,7s) = s/0,7.","f":0},"11":{"t":"p är 5 eller 7, och m<p. Eftersom 35 = 5·7 delas jämnt av både 5 och 7, blir 35m/p ett heltal oavsett värde. Övriga alternativ garanteras inte (t.ex. m/p < 1).","f":0},"12":{"t":"Vid T: summan = 3·24 = 72. Tre år efter T: Bianca+Cecilia = 2·25 = 50. Vid T var de 50 − 6 = 44, så Annica vid T = 72 − 44 = 28. Tre år efter T: 28 + 3 = 31.","f":0},"13":{"t":"(2x)² = 4x², medan II = 2x². För x≠0 är 4x² > 2x², så I är större.","f":0},"14":{"t":"f(−1) = 1 + 3 + 2 = 6. f(3) = 9 − 9 + 2 = 2. I = 6 > II = 2.","f":0},"15":{"t":"5⁵/5³ = 5² = 25. 5²⁸/5²⁶ = 5² = 25. Lika.","f":0},"16":{"t":"Rektangel: 6x·0,5x = 3x². Cirkel: πx² ≈ 3,14x². Eftersom π > 3 är cirkelns area större.","f":0},"17":{"t":"Jämför kvadraterna: (3√6)² = 54 och (6√3)² = 108. Alltså är 6√3 större.","f":0},"18":{"t":"x² = 25 ger x = 5 eller −5, alltså y = x−2 = 3 eller −7. II = √16 = 4. I båda fallen är y < 4, så II är alltid större.","f":0},"19":{"t":"A − 6 = A/3 → 2A = 18 → A = 9 år idag. Om 6 år: 9 + 6 = 15 år, vilket är mindre än 18.","f":0},"20":{"t":"x/y = −1 betyder x = −y, alltså x + y = 0. Lika med II.","f":0},"21":{"t":"Produkt 12 ger paren (1,12), (2,6), (3,4) med medelvärden 6,5; 4; 3,5. Medelvärdet kan vara större, lika med eller mindre än 4 → otillräckligt.","f":0},"22":{"t":"Likbent säger inte vilka vinklar som är lika. C kan vara vilken vinkel som helst, så A+B = 180−C är obestämt jämfört med 90° → otillräckligt.","f":0},"23":{"t":"(1) ensam: komedi och skräck hamnar i salong 1/3 men inte i vilken ordning. (2) ensam: komedi i 1, skräck i 2 eller 3 (obestämt). Tillsammans: komedi=1, skräck måste vara i 3 (uppfyller båda), drama=2. Bestämt.","f":0},"24":{"t":"Antal stora röda = (antal röda) − (antal små röda). (2) ger 5 små röda, men det exakta antalet röda är okänt (bara >42,5 från (1)), så även tillsammans går det inte att bestämma.","f":0},"25":{"t":"(2): dubbel fart halverar tiden, t − t/2 = 7,5 min → t = 15 min = 0,25 h (men fart okänd). (1): fart 15 km/h (men tid okänd). Tillsammans: sträcka = 15·0,25 = 3,75 km.","f":0},"26":{"t":"(2) ensam räcker: blå = 3/7·56 = 24, gröna = 5/14·56 = 20, röda = 56 − 24 − 20 = 12. (1) ger bara förhållandet blå:gröna och lämnar antalet obestämt.","f":0},"27":{"t":"Villkoren ger d1=2·d5 och d1 jämn, samt d4=2·d1 (kräver d1≤4), alltså d1 = 2 eller 4. Båda ger giltiga tal (t.ex. 25741 och 43782) → talet är inte entydigt ens tillsammans.","f":0},"28":{"t":"Med AB = a är AC = 3a, AM = 1,5a och BC = 2a. (1): CM = AC−AM = 1,5a = 6 → a = 4 → BC = 8. (2): AB = a = 4 → BC = 8. Var för sig räcker.","f":0},"29":{"t":"07/08: familjegrupper ≈ 207 → totalt ≈ 207·6 ≈ 1242 lodjur. Döda 07/08 ≈ 100. Förhållandet 100:1242 ≈ 1:12,4 ≈ 1:13.","f":0},"30":{"t":"08/09: totalt döda ≈ 213, övrig dödlighet ≈ 53. Dödade i jakt (licens+skydd) ≈ 213 − 53 ≈ 160. Andel ≈ 160/213 ≈ 75 %.","f":0},"31":{"t":"En familjegrupp = 1 hona + i snitt 2 ungar = 3 individer. Flest familjegrupper (08/09) ≈ 288. Individer ≈ 288·3 ≈ 864 ≈ 870.","f":0},"32":{"t":"Tre största orsakerna: fallolycka 73 618, orsak 23 = 24 977, orsak 20 = 10 928. Summa ≈ 109 500 av totalt 166 119 ≈ 0,66 ≈ 2/3.","f":0},"33":{"t":"Rök/öppen eld: kvinnor 217, män 413, totalt 630. Kvinnors andel ≈ 217/630 ≈ 34 %, alltså cirkeln där den grå (kvinnor) delen är ungefär en tredjedel → A.","f":0},"34":{"t":"Kvinnor: 1799 + 554 = 2353. Män: 1081 + 672 = 1753. Skillnad = 2353 − 1753 = 600.","f":0},"35":{"t":"Sista tre åren (08–10): 59,6+55,5+80,3 = 195,4. Första tre (00–02): 24,3+20,6+13,8 = 58,7. Skillnad ≈ 136,7 tusen ≈ 135 000 hektar.","f":0},"36":{"t":"Norrbotten 10,6 + Jämtland 16,5 = 27,1 av totalt 80,3 tusen hektar ≈ 0,34 ≈ 1/3.","f":0},"37":{"t":"Norr (Norrbotten 10,6 + Västerbotten 13,1 + Jämtland 16,5 + Västernorrland 13,8) = 54,0. Söder = totalt 80,3 − 54,0 = 26,3 tusen ≈ 26 300 hektar.","f":0},"38":{"t":"I översta diagrammet skär förstföderskor 24,9 år och omföderskor 29,0 år samtidigt runt år 1980.","f":0},"39":{"t":"Andelen 30–34-åriga förstföderskor 1990 ≈ 10 %. Kurvan når 20 % (fördubbling) omkring 1998, dvs efter cirka 8 år.","f":1},"40":{"t":"Omföderskor 2010: −19 år ≈ 0,5 % (minst), 20–24 ≈ 8 %, 25–29 ≈ 22 %, 35+ ≈ 30 %, 30–34 ≈ 40 % (störst). Ordning: −19 < 20–24 < 25–29 < 35+ < 30–34.","f":0}},"q1":{"1":{"t":"2(x+4)/2 förkortas till (x+4). Uttrycket blir x+4+8 = x+12.","f":0},"2":{"t":"L1∥L2. De givna 131° och 113° ger inre vinklar på transversalerna: 180−131=49° och 180−113=67°. Vinkeln v är tredje vinkeln i triangeln som bildas: 180−49−67 = 64°.","f":0},"3":{"t":"3(x−4)=2(x+2) → 3x−12 = 2x+4 → x = 16.","f":0},"4":{"t":"Fyra på varandra följande heltal med medelvärde 4,5 har summan 18, alltså 3,4,5,6. Medianen = (4+5)/2 = 4,5.","f":0},"5":{"t":"Skärning vid x=1. Sätt in i y=2x−1: y=2·1−1=1. Då gäller 1=k·1+3 → k = −2.","f":0},"6":{"t":"1000 m på 50 s = 20 m/s. 20·3,6 = 72 km/h.","f":0},"7":{"t":"Nämnaren 2/5 − 5/6 = 12/30 − 25/30 = −13/30. Alltså 1/(−13/30) = −30/13.","f":0},"8":{"t":"Triangel ABD är rätvinklig (A): BD=√(3²+4²)=5. Triangel BDC är rätvinklig (D): BC=√(5²+12²)=√169=13 cm.","f":0},"9":{"t":"x−y=0 ger x=y. Då är xy = y·y = y². Säkert lika med y².","f":0},"10":{"t":"Ett negativt tal upphöjt till en udda exponent blir negativt (jämn exponent ger positivt). För att xⁿ<0 för negativt x måste n vara udda.","f":0},"11":{"t":"Slutpunkt: (5,0) → (5,6) → (8,6). Avstånd från origo = √(8²+6²) = √100 = 10 längdenheter.","f":0},"12":{"t":"√12 = 2√3 och √48 = 4√3. Summan = 6√3.","f":0},"13":{"t":"För x>0 är √x·√x = x, alltså lika med Kvantitet II. Svar C.","f":0},"14":{"t":"P(en fyra och en femma) = {4,5} och {5,4} = 2/36. P(summa 3) = {1,2},{2,1} = 2/36. Lika.","f":0},"15":{"t":"5/13 ≈0,385 > 4/15 ≈0,267, så I är positiv. II är exakt samma differens fast omvänd (negativ). Alltså I > II.","f":0},"16":{"t":"Strålarna delar den räta linjen (180°) i vinklarna x, y, y, x. Alltså 2x+2y=180° → x+y=90° = Kvantitet II.","f":0},"17":{"t":"Eftersom x>0 är z²=x²+y² > y², och med positiva tal ger det z > y. Kvantitet II större.","f":0},"18":{"t":"Sätt B=100, då A=80. I: 80·0,95 = 76. II: 100·0,75 = 75. I > II.","f":0},"19":{"t":"Arean = π·5² = 25π ≈ 78,5 cm² > 75 cm². Kvantitet I större.","f":0},"20":{"t":"Ur xy=z fås z/y = xy/y = x. Alltså Kvantitet II = x = Kvantitet I. Lika.","f":0},"21":{"t":"k₁ för L1 = (7−1)/(−3−2) = 6/−5 = −1,2. Vinkelrät linje: k₂ = −1/k₁ = 5/6 ≈ 0,83. II > I.","f":0},"22":{"t":"I=2·10ˣ, II=(2·10)ˣ=20ˣ. Vid x=0 är I>II, vid x=1 lika, vid x=2 är II>I. Beror på x → otillräcklig information.","f":0},"23":{"t":"Vi vet 20 spelar fotboll och 10 innebandy, men inget om överlappet (hur många som spelar båda eller ingen). Går ej att bestämma ens tillsammans. Svar E.","f":0},"24":{"t":"Varje påstående ger bara en punkt (definierar ingen linje). Tillsammans: (4,6) och (6,4) ger linjen y=−x+10, som vid x=5 ger y=5 → ja. Krävs båda.","f":0},"25":{"t":"Delbart med 100 medför delbart med 5 (räcker ensamt). Delbart med 15 (=3·5) medför också delbart med 5 (räcker ensamt). Var för sig.","f":0},"26":{"t":"(1): al>björk och rönn ej högst → alltså al högst (räcker). (2): säger bara att al och björk > rönn, inget om al mot björk (räcker ej). Endast (1).","f":0},"27":{"t":"Långärmad-barn=10. (1): 10=25% av barn → barn=40, vuxen=60. (2): 10=20% av långärmade → långärmade=50, kortärmade=50. Tillsammans: kortärmad-vuxen = 50−30 = 20. Krävs båda.","f":0},"28":{"t":"x=2y. (1): 'ett tal är 7' är tvetydigt (y=7 eller y=3,5). (2): x+y=21 med x=2y ger 3y=21 → y=7 (räcker ensamt). Endast (2).","f":0},"29":{"t":"Renar per renägare <30: Skogssamebyar (26) och Koncessionssamebyar (13). Kvinnoandel >1/3: Skogs 304/830≈37% (ja), Koncessions 187/795≈24% (nej). Endast Skogssamebyar uppfyller båda villkoren.","f":0},"30":{"t":"Kvinnor i hela riket: 1843 (2016) mot 1603 (1995). Ökning = 240/1603 ≈ 15%.","f":0},"31":{"t":"Jämtland fjällsamebyar: 49241/12 ≈ 4103 renar/sameby. Västerbotten: 48945/7 ≈ 6992. Skillnad ≈ 2889 ≈ 2900.","f":0},"32":{"t":"Villkor: |årsavgift−årshyra|<1000 kr/m² och insats>1500 tkr. Kommuner >75000: ca 1510−640≈870 (<1000) och insats ≈1860 (>1500) → uppfyller. Stockholm/Göteborg har skillnad >1000 (~1060); Kommuner <75000 har insats ~1370 (<1500).","f":0},"33":{"t":"Uppmätt: årshyra i mindre kommuner (<75000) ≈1340 kr/m² < större kommuner (>75000) ≈1510. Alltså hade mindre kommuner lägre årshyra för hyresrätt. Svar B.","f":0},"34":{"t":"Insats i kommuner <75000 ≈ 1370 tkr. Jämfört med rikssnittet 2616 tkr: 1370/2616 ≈ 0,52 → ungefär hälften så hög.","f":0},"35":{"t":"På kartan visar de prickade (skuggade) 'korvarna' med riktningspilar hur långt en halvtimmes tågresa når från orter med minst 2000 invånare. Följ banan ut från Uppsala åt varje håll: halvtimmeszonen täcker Brunna (station 11) på västra linjen, Vattholma (station 18) på norra linjen och Örsundsbro (station 8) på sydvästra linjen - alla tre ligger inom Uppsalas skuggade halvtimmeszon. På östra linjen mot Faringe når halvtimmeszonen fram till Bärby (station 29), men Marielund (station 30) ligger precis utanför gränsen. Alltså är det Marielund som låg mer än en halvtimmes tågresa från Uppsala. Svar B.","f":0},"36":{"t":"På tågnätet går resan Uppsala–Hallstavik österut via Faringe (33) och vidare via knutpunkten Rimbo (48) upp mot Hallstavik. Alltså passeras Faringe och Rimbo. Verifierat på kartan.","f":0},"37":{"t":"Medelhastighet = sträcka / tid. Tid: den prickade halvtimmeszonen (med riktningspil) söderut från Tierp når ungefär fram till Örbyhus (station 21), och Knypplan (station 20) ligger precis vid zonens ytterkant. Restiden Tierp-Knypplan är därför ungefär en halvtimme, dvs 0,5 h. Sträcka: mät banan Tierp-Knypplan mot kartans kilometerskala (0-30 km) - det motsvarar ungefär 20 km. Medelhastighet = 20 km / 0,5 h = 40 km/h. Svar B.","f":0},"38":{"t":"Total energianvändning steg från ca 440 TWh (1970) till ca 580 TWh (2017). Ökningen ≈ 140/440 ≈ 30%.","f":0},"39":{"t":"1984 var totala användningen ca 470 TWh; 15% ≈ 70 TWh. Bandet Inrikes transporter är ca 65–70 TWh tjockt det året (Industri och Bostäder är betydligt större). Svar D.","f":0},"40":{"t":"2010: kärnbränsle-tillförsel ≈185 TWh, förluster i kärnkraften ≈125 TWh (verkningsgraden ~1/3 ger stora förluster). Skillnaden ≈ 60 TWh.","f":0}}}};
